import React, { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';
import './Lag.css';
import CoverageFunnel from './CoverageFunnel';
import RecordBrowser from './RecordBrowser';

// Publication delay by language: for each period a book covers, when did
// books in each language start to appear, and how long after the events?
// Data: public/data/lag_data.json (built by scripts/make_lag_data.py); the
// 8th field of each record lists its language(s).

const W = 1000;
const M0 = { top: 34, right: 30, bottom: 40, left: 120 };
const LANE_H = 13;
const ROW_PAD = 14;
const LANG_COLORS = {
  Ukrainian: '#f2c230', Russian: '#e0524a', Polish: '#ec6fc4', English: '#52a9ff',
  German: '#7bd88f', French: '#b08cff', Latin: '#aaa', Italian: '#f59e57',
};
// pseudo-language: every record once, whatever its language(s)
const TOTAL = 'All languages (total)';
const withTotal = (ls) => [TOTAL, ...ls];
const colorOf = (l) => (l === TOTAL ? '#e6e6e6' : LANG_COLORS[l] || '#9a9a9a');
const DEFAULT_LANGS = [TOTAL, 'Ukrainian', 'Russian', 'Polish'];

function binOf(y, size) {
  if (y < 1500) return 0;
  return Math.floor((y - 1) / size) * size + 1;
}
function binLabel(b, size) {
  if (b === 0) return 'Before 1500';
  return `${b}–${b + size - 1}`;
}

export default function LagLanguages() {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [langs, setLangs] = useState(DEFAULT_LANGS);
  const [mode, setMode] = useState('year'); // 'year' | 'lag'
  const [binSize, setBinSize] = useState(50);
  const [ref, setRef] = useState('end');
  const [maxSpan, setMaxSpan] = useState(100);
  const [useTitles, setUseTitles] = useState(false);
  const [startMode, setStartMode] = useState('min'); // 'min' | 'p5'
  const [rowMode, setRowMode] = useState('topic'); // 'topic' (all books) | 'period' (dated subjects only)
  const [all, setAll] = useState(null);
  const [useOpen, setUseOpen] = useState(false);
  const [cell, setCell] = useState(null); // { key, lang }
  const [cellLimit, setCellLimit] = useState(25);

  useEffect(() => {
    let cancelled = false;
    fetch(`${process.env.PUBLIC_URL}/data/lag_data.json`)
      .then((r) => r.json())
      .then((d) => { if (!cancelled) setData(d); })
      .catch((e) => { console.error('Failed to load lag_data.json', e); if (!cancelled) setError(e); });
    fetch(`${process.env.PUBLIC_URL}/data/lag_all.json`)
      .then((r) => r.json())
      .then((d) => { if (!cancelled) setAll(d); })
      .catch((e) => { console.error('Failed to load lag_all.json', e); if (!cancelled) setError(e); });
    return () => { cancelled = true; };
  }, []);

  // usable records, one entry per record
  const topicMode = rowMode === 'topic';
  const effMode = topicMode ? 'year' : mode;
  const recs = useMemo(() => {
    if (!data || !all) return [];
    if (topicMode) {
      return all.records.filter((r) => r[2] > 0 && r[4].length)
        .map(([id, title, pubY, bands, ls, , s, e]) => ({ id, title, pubY, bands, langs: ls, s, e }));
    }
    const out = [];
    for (const r of data.records) {
      const [id, title, pubY, s, e, , src, ls] = r;
      if (src === 1 && !useTitles) continue;
      if (src === 2 && !useOpen) continue;
      if ((src !== 2 && e - s > maxSpan) || !ls || !ls.length) continue;
      // open-ended periods: only the start is meaningful, so the delay is a maximum
      const covered = src === 2 ? s : ref === 'end' ? e : Math.round((s + e) / 2);
      const lag = pubY - covered;
      if (lag < 0) continue;
      out.push({ id, title, pubY, s, e, covered, lag, langs: ls, src });
    }
    return out;
  }, [data, all, topicMode, ref, maxSpan, useTitles, useOpen]);

  const langTotals = useMemo(() => {
    const c = {};
    for (const r of recs) for (const l of withTotal(r.langs)) c[l] = (c[l] || 0) + 1;
    return Object.entries(c).sort((a, b) => b[1] - a[1]);
  }, [recs]);

  // cells[bin][lang] -> sorted values
  const { rows } = useMemo(() => {
    const cells = new Map();
    for (const r of recs) {
      const keys = topicMode ? (r.bands.length ? r.bands : [-1]) : [binOf(r.covered, binSize)];
      const v = effMode === 'year' ? r.pubY : r.lag;
      for (const b of keys) {
        for (const l of withTotal(r.langs)) {
          if (!langs.includes(l)) continue;
          if (!cells.has(b)) cells.set(b, {});
          (cells.get(b)[l] = cells.get(b)[l] || []).push(v);
        }
      }
    }
    const keyList = [...cells.keys()];
    const total = (b) => Object.values(cells.get(b)).reduce((a, v) => a + v.length, 0);
    keyList.sort(topicMode ? (a, b) => total(b) - total(a) : (a, b) => a - b);
    const rows = keyList.map((b) => {
      const byLang = {};
      for (const l of langs) {
        const v = cells.get(b)[l];
        if (!v) continue;
        v.sort((x, y) => x - y);
        const p5 = d3.quantileSorted(v, 0.05);
        const robust = startMode === 'p5' && v.length >= 5;
        byLang[l] = { n: v.length, min: v[0], start: robust ? Math.round(p5) : v[0], approx: startMode === 'p5' && v.length < 5, med: d3.quantileSorted(v, 0.5), max: v[v.length - 1],
          q1: d3.quantileSorted(v, 0.25), q3: d3.quantileSorted(v, 0.75) };
      }
      const label = topicMode ? (b < 0 ? 'No topic theme' : all.bandLabel[b]) : binLabel(b, binSize);
      return { key: b, label, byLang };
    });
    return { rows };
  }, [recs, all, topicMode, langs, effMode, binSize, startMode]);

  // cumulative share of each language's books by publication year
  const cum = useMemo(() => {
    const by = {};
    for (const r of recs) for (const l of withTotal(r.langs)) if (langs.includes(l)) (by[l] = by[l] || []).push(r.pubY);
    return Object.entries(by).map(([l, ys]) => {
      ys.sort((a, b) => a - b);
      const q = (p) => d3.quantileSorted(ys, p);
      return { l, n: ys.length, ys, q10: q(0.1), q25: q(0.25), q50: q(0.5), q75: q(0.75), first: ys[0] };
    }).sort((a, b) => LANG_ORDER(a.l) - LANG_ORDER(b.l));
  }, [recs, langs]);

  const keysOf = (r) => (topicMode ? (r.bands.length ? r.bands : [-1]) : [binOf(r.covered, binSize)]);
  const cellRecs = useMemo(() => {
    if (!cell) return [];
    return recs.filter((r) => (cell.lang === TOTAL || r.langs.includes(cell.lang)) && keysOf(r).includes(cell.key))
      .sort((a, b) => a.pubY - b.pubY);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cell, recs, topicMode, binSize]);

  if (error) return <div className="lag-root"><p>Could not load the data.</p></div>;
  if (!data || !all) return <div className="lag-root"><p className="lag-muted">Loading…</p></div>;

  const M = { ...M0, left: topicMode ? 270 : 120 };
  const laneCount = Math.max(1, langs.length);
  const rowH = laneCount * LANE_H + ROW_PAD;
  const H = M.top + rows.length * rowH + M.bottom;
  const allV = rows.flatMap((r) => Object.values(r.byLang).flatMap((c) => [c.min, c.max]));
  const lo = allV.length ? d3.min(allV) : 0;
  const hi = allV.length ? d3.max(allV) : 1;
  const x = effMode === 'year'
    ? d3.scaleLinear().domain([Math.floor(lo / 10) * 10 - 5, Math.ceil(hi / 10) * 10 + 5]).range([M.left, W - M.right])
    : d3.scaleSymlog().constant(15).domain([0, Math.max(hi, 20)]).range([M.left, W - M.right]).nice();
  const ticks = effMode === 'year' ? x.ticks(10) : [0, 5, 10, 25, 50, 100, 250, 500, 1000].filter((t) => t <= x.domain()[1]);
  const firstLabel = startMode === 'p5' ? (effMode === 'year' ? 'start (5th percentile, earliest if under 5 books)' : 'fastest 5%') : (effMode === 'year' ? 'first book' : 'fastest book');
  const toggleLang = (l) => setLangs((cur) => (cur.includes(l) ? cur.filter((z) => z !== l) : [...cur, l]));
  const shownLangs = langs.slice().sort((a, b) => (LANG_ORDER(a) - LANG_ORDER(b)));
  function LANG_ORDER(l) { const i = DEFAULT_ORDER.indexOf(l); return i < 0 ? 99 : i; }

  const gap = (r, l) => {
    const c = r.byLang[l], u = r.byLang.Ukrainian;
    if (!c || !u || l === 'Ukrainian') return '';
    const d = c.start - u.start;
    return ` (${d > 0 ? '+' : ''}${d} vs Ukrainian)`;
  };

  return (
    <div className="lag-root">
      <div className="lag-links">
        <a href="#/">← About this project</a>
        <a href="#/lag">Publication delay by topic →</a>
        <a href="#/topics">Subject themes river →</a>
        <a href="#/map">Map &amp; network explorer →</a>
        <a href="#/influence">Russia &amp; Poland river →</a>
      </div>
      <h1>Publication delay by language</h1>
      <p className="lag-subtitle">
        When did books in different languages start to appear on each topic or period of Ukrainian
        history, and how long after the events? Each row is a topic (or a period covered); each coloured lane is a language.
        The hollow diamond is the earliest book, the dot the median, and the thin line runs from the
        earliest to the latest.
      </p>
      <div className="lag-method">
        <b>Records shown now:</b> {recs.length.toLocaleString()} distinct records under the selected row mode and filters. The topic view uses records with a publication year and language; the period view uses dated subject periods and applies the selected span and inclusion settings. A record can appear in multiple topic rows or language lanes.
        <br /><br />
        {topicMode ? (
          <>
            <b>What is measured:</b> all {recs.length.toLocaleString()} catalog records that have a publication
            year and a language (of {data.totalRecords.toLocaleString()}; the rest have no publication year).
            No subject period is needed here, so this uses the whole catalog. Rows are the same topic
            themes as the river charts, largest first; a book on several topics appears in each, and a
            bilingual book counts once in each of its languages. Books with no topic theme are grouped
            at the bottom. “First book” means the first one held in this catalog, not the first ever published.
          </>
        ) : (
          <>
            <b>What is measured:</b> {recs.length.toLocaleString()} catalog records (of {data.totalRecords.toLocaleString()})
            have both a datable subject period and a language. A bilingual record counts once in each of its
            languages. Periods are grouped by their {ref === 'end' ? 'end' : 'midpoint'} year. The catalog
            is a library collection, so “first book” means the first one held here, not the first ever
            published, and small cells (few books) should be read as indicative only.
          </>
        )}
      </div>

      {!topicMode && <CoverageFunnel data={data} titleExtra={data.records.filter((r) => r[6] === 1).length} useTitles={useTitles} openExtra={data.records.filter((r) => r[6] === 2).length} useOpen={useOpen} />}

      <div className="lag-toolbar">
        <label>Rows are
          <select value={rowMode} onChange={(e) => setRowMode(e.target.value)}>
            <option value="topic">topics (all books)</option>
            <option value="period">periods covered (dated subjects only)</option>
          </select>
        </label>
        {!topicMode && <label>Show
          <select value={mode} onChange={(e) => setMode(e.target.value)}>
            <option value="year">publication year</option>
            <option value="lag">delay in years</option>
          </select>
        </label>}
        {!topicMode && <label>Group periods by
          <select value={binSize} onChange={(e) => setBinSize(+e.target.value)}>
            <option value={100}>century</option>
            <option value={50}>50 years</option>
            <option value={25}>25 years</option>
          </select>
        </label>}
        <label title="The 5th percentile ignores a lone early outlier; it needs at least 5 books in a cell">Mark the start as
          <select value={startMode} onChange={(e) => setStartMode(e.target.value)}>
            <option value="min">earliest book</option>
            <option value="p5">5th percentile (robust)</option>
          </select>
        </label>
        {!topicMode && <label>Measure from the
          <select value={ref} onChange={(e) => setRef(e.target.value)}>
            <option value="end">end of the period</option>
            <option value="mid">middle of the period</option>
          </select>
        </label>}
        {!topicMode && <label>Ignore periods wider than
          <input type="range" min={10} max={200} step={10} value={maxSpan} onChange={(e) => setMaxSpan(+e.target.value)} />
          <b>{maxSpan} yrs</b>
        </label>}
        {!topicMode && <label title="Open-ended periods or periods that run past the publication year; delay is measured from the period's start, so it is a maximum">
          <input type="checkbox" checked={useOpen} onChange={(e) => setUseOpen(e.target.checked)} />
          Include open-ended periods
        </label>}
        {!topicMode && <label>
          <input type="checkbox" checked={useTitles} onChange={(e) => setUseTitles(e.target.checked)} />
          Also use dates found in titles
        </label>}
      </div>
      <div className="lag-toolbar">
        <span>Languages:</span>
        {langTotals.slice(0, 9).map(([l, n]) => (
          <label key={l}>
            <input type="checkbox" checked={langs.includes(l)} onChange={() => toggleLang(l)} />
            <span className="lag-swatch" style={{ background: colorOf(l) }} /> {l} <span className="lag-muted">({n})</span>
          </label>
        ))}
      </div>

      {rows.length === 0 ? <p className="lag-muted">Select at least one language.</p> : (
        <svg className="lag-chart" viewBox={`0 0 ${W} ${H}`} role="img"
          aria-label="First and median publication by language and period covered">
          {ticks.map((t) => (
            <g key={t}>
              <line className="lag-grid" x1={x(t)} x2={x(t)} y1={M.top - 6} y2={H - M.bottom} />
              <text className="lag-tick" x={x(t)} y={H - M.bottom + 16} textAnchor="middle">{t}</text>
            </g>
          ))}
          <text className="lag-axis-title" x={(M.left + W - M.right) / 2} y={H - 6} textAnchor="middle">
            {effMode === 'year' ? 'publication year' : 'years between the period covered and publication'}
          </text>
          <text className="lag-axis-title" x={M.left - 10} y={M.top - 14} textAnchor="end">{topicMode ? 'topic' : 'period covered'}</text>
          {rows.map((r, ri) => {
            const y0 = M.top + ri * rowH;
            return (
              <g key={r.key}>
                {ri % 2 === 0 && <rect x={0} y={y0} width={W} height={rowH} fill="rgba(255,255,255,0.03)" />}
                <text className="lag-label" x={M.left - 10} y={y0 + rowH / 2 + 4} textAnchor="end">{r.label}</text>
                {shownLangs.map((l, li) => {
                  const c = r.byLang[l];
                  if (!c) return null;
                  const cy = y0 + ROW_PAD / 2 + li * LANE_H + LANE_H / 2;
                  const col = colorOf(l);
                  const tip = `${l}, period ${r.label}: ${c.n} book${c.n > 1 ? 's' : ''}; ${firstLabel} ${Math.round(c.start)}${gap(r, l)}; median ${Math.round(c.med)}; latest ${Math.round(c.max)}`;
                  return (
                    <g key={l} style={{ cursor: 'pointer' }} onClick={() => { setCell({ key: r.key, lang: l, label: r.label }); setCellLimit(25); }}>
                      <title>{tip}</title>
                      <rect x={M.left} y={cy - LANE_H / 2} width={W - M.left - M.right} height={LANE_H} fill="transparent" />
                      <line x1={x(c.min)} x2={x(c.max)} y1={cy} y2={cy} stroke={col} strokeWidth={1.5} opacity={0.55} />
                      {c.n >= 5 && <rect x={x(c.q1)} y={cy - 3} width={Math.max(2, x(c.q3) - x(c.q1))} height={6} fill={col} opacity={0.35} />}
                      {c.n >= 3 && <circle cx={x(c.med)} cy={cy} r={3.8} fill={col} />}
                      <path d={`M${x(c.start)},${cy - 5}L${x(c.start) + 5},${cy}L${x(c.start)},${cy + 5}L${x(c.start) - 5},${cy}Z`}
                        fill="#0b0d10" stroke={col} strokeWidth={1.8} opacity={c.approx ? 0.45 : 1} />
                    </g>
                  );
                })}
              </g>
            );
          })}
        </svg>
      )}

      {rows.length > 0 && (
        <>
          <h2 style={{ marginTop: 26 }}>When each language started, by {topicMode ? 'topic' : 'period covered'}</h2>
          <p className="lag-muted">
            {startMode === 'p5' ? '5th-percentile ' : 'Earliest '}{effMode === 'year' ? 'publication year' : 'delay'}{startMode === 'p5' ? ' (* = fewer than 5 books, so the earliest book is shown)' : ''} in the collection, with the number of books in brackets.
            {effMode === 'year' ? ' The figure after it shows the gap to the earliest Ukrainian book on the same period.' : ''}
          </p>
          <div style={{ overflowX: 'auto' }}>
            <table className="lag-table">
              <thead>
                <tr><th>{topicMode ? 'Topic' : 'Period covered'}</th>{shownLangs.map((l) => <th key={l} style={{ color: colorOf(l) }}>{l}</th>)}</tr>
              </thead>
              <tbody>
                {rows.map((r) => (
                  <tr key={r.key}>
                    <td>{r.label}</td>
                    {shownLangs.map((l) => {
                      const c = r.byLang[l];
                      return <td key={l} style={c ? { cursor: 'pointer' } : undefined} onClick={c ? () => { setCell({ key: r.key, lang: l, label: r.label }); setCellLimit(25); } : undefined}>{c ? <>{Math.round(c.start)}{c.approx ? '*' : ''} <span className="lag-muted">({c.n}){effMode === 'year' ? gap(r, l).replace(' vs Ukrainian', '') : ''}</span></> : <span className="lag-muted">—</span>}</td>;
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
      {cell && (
        <div className="lag-detail">
          <div className="lag-detail-head">
            <h2><span className="lag-swatch" style={{ background: colorOf(cell.lang) }} />
              {cell.lang} books — {cell.label} <span className="lag-muted">({cellRecs.length})</span></h2>
            <button onClick={() => setCell(null)}>Close</button>
          </div>
          <p className="lag-muted">Oldest first. Click another dot or table cell to switch.</p>
          <table className="lag-table">
            <thead><tr><th>Title</th><th>Published</th><th>Languages</th></tr></thead>
            <tbody>
              {cellRecs.slice(0, cellLimit).map((r) => (
                <tr key={r.id}>
                  <td>{r.title}{r.src === 1 && <span className="lag-badge">from title</span>}{r.src === 2 && <span className="lag-badge" title="Open-ended period: delay is a maximum">upper bound</span>}</td>
                  <td>{r.pubY}</td><td>{r.langs.join(', ')}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {cellLimit < cellRecs.length && (
            <button className="lag-more" onClick={() => setCellLimit(cellLimit + 50)}>Show {Math.min(50, cellRecs.length - cellLimit)} more</button>
          )}
        </div>
      )}

      {cum.length > 0 && <CumulativeChart cum={cum} />}

      <RecordBrowser all={all} />
    </div>
  );
}

function CumulativeChart({ cum }) {
  const [yMode, setYMode] = useState('share'); // 'share' | 'log'
  const CW = 1000, CH = 330, cm = { top: 20, right: 30, bottom: 40, left: 60 };
  const lo = d3.min(cum, (c) => c.first), hi = d3.max(cum, (c) => c.ys[c.ys.length - 1]);
  const x = d3.scaleLinear().domain([Math.floor(lo / 10) * 10, Math.ceil(hi / 5) * 5]).range([cm.left, CW - cm.right]);
  const maxN = d3.max(cum, (c) => c.n);
  const isLog = yMode === 'log';
  const y = isLog
    ? d3.scaleLog().domain([1, Math.max(10, maxN)]).range([CH - cm.bottom, cm.top]).nice()
    : d3.scaleLinear().domain([0, 1]).range([CH - cm.bottom, cm.top]);
  const yTicks = isLog ? [1, 10, 100, 1000, 10000].filter((t) => t <= y.domain()[1]) : [0, 0.25, 0.5, 0.75, 1];
  const yOf = (i, n) => (isLog ? y(i) : y(i / n));
  return (
    <>
      <h2 style={{ marginTop: 30 }}>How each language's output accumulates</h2>
      <div className="lag-toolbar" style={{ marginTop: 8 }}>
        <label>Vertical axis
          <select value={yMode} onChange={(e) => setYMode(e.target.value)}>
            <option value="share">share of the language's books (0–100%)</option>
            <option value="log">number of books (log scale)</option>
          </select>
        </label>
      </div>
      <p className="lag-muted" style={{ maxWidth: 880 }}>
        {isLog
          ? 'Each line counts the books published up to a given year, on a log scale: equal vertical steps mean the count has multiplied by the same factor. This keeps small languages visible next to Ukrainian and shows absolute volume, so a small collection is not mistaken for a late start.'
          : 'Each line shows the share of a language\'s books that had been published by a given year. A line that rises early means the language wrote about these topics early; a line that stays flat and then jumps means most of its books are recent. Shares hide volume, so switch to log counts to compare sizes.'}
      </p>
      <svg className="lag-chart" viewBox={`0 0 ${CW} ${CH}`} role="img" aria-label="Cumulative books by publication year">
        {yTicks.map((t) => (
          <g key={t}>
            <line className="lag-grid" x1={cm.left} x2={CW - cm.right} y1={y(t)} y2={y(t)} />
            <text className="lag-tick" x={cm.left - 8} y={y(t) + 4} textAnchor="end">{isLog ? t.toLocaleString() : `${Math.round(t * 100)}%`}</text>
          </g>
        ))}
        {x.ticks(10).map((t) => (
          <text key={t} className="lag-tick" x={x(t)} y={CH - cm.bottom + 16} textAnchor="middle">{t}</text>
        ))}
        <text className="lag-axis-title" x={(cm.left + CW - cm.right) / 2} y={CH - 6} textAnchor="middle">publication year</text>
        {cum.map((c) => {
          const base = isLog ? y(1) : y(0);
          const pts = c.ys.map((yr, i) => [x(yr), yOf(i + 1, c.n)]);
          const path = d3.line().curve(d3.curveStepAfter)([[x(c.first), base], ...pts]);
          return <path key={c.l} d={path} fill="none" stroke={colorOf(c.l)} strokeWidth={2.2}><title>{`${c.l}: ${c.n} books`}</title></path>;
        })}
      </svg>
      <div style={{ overflowX: 'auto' }}>
        <table className="lag-table">
          <thead><tr><th>Language</th><th>Books</th><th>Earliest</th><th>10% by</th><th>25% by</th><th>Half by</th><th>75% by</th></tr></thead>
          <tbody>
            {cum.map((c) => (
              <tr key={c.l}>
                <td style={{ color: colorOf(c.l) }}>{c.l}</td>
                <td>{c.n}</td><td>{Math.round(c.first)}</td>
                <td>{Math.round(c.q10)}</td><td>{Math.round(c.q25)}</td><td>{Math.round(c.q50)}</td><td>{Math.round(c.q75)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  );
}
const DEFAULT_ORDER = [TOTAL, 'Ukrainian', 'Russian', 'Polish', 'English', 'German', 'French'];
