import React, { useEffect, useMemo, useRef, useState } from 'react';
import { flushSync } from 'react-dom';
import { ZoomMap, useWorld } from './ZoomMap';
import { useLocale } from '../i18n';

const base = () => (process.env.PUBLIC_URL || '').replace(/\/$/, '');
const get  = (f) => fetch(`${base()}/data/${f}`).then((r) => r.json());

const GC = {
  rulers:      '#5db3ee',
  thinkers:    '#2dc79b',
  fighters:    '#f08a4b',
  politicians: '#e08dbf',
  others:      '#b3bac2',
};

const YEAR_MIN = 1595;
const YEAR_MAX = 2026;
const N_YEARS  = YEAR_MAX - YEAR_MIN; // 431 steps, slider 0..431

const fmtY = (y, uk) => {
  if (y == null) return '?';
  const v = Math.floor(y);
  return v < 0 ? `${-v} ${uk ? 'до н. е.' : 'BCE'}` : String(v);
};

// "Khmelnytsky, Bohdan" → "Bohdan"
const firstName = (q) => {
  if (!q.f) return '';
  const c = q.f.indexOf(',');
  return c >= 0 ? q.f.slice(c + 1).trim() : '';
};

// "Bohdan Khmelnytsky", with LC heading fallback for people without f field
const fullName = (q, lcHeading) => {
  const fn = firstName(q);
  if (fn) return `${fn} ${q.n}`;
  if (lcHeading) {
    const base2 = lcHeading.split(' -- ')[0].replace(/,\s*\d{4}.*$/, '').trim();
    const comma = base2.indexOf(',');
    if (comma >= 0) {
      const sur = base2.slice(0, comma).trim();
      let rest = base2.slice(comma + 1).trim();
      const paren = rest.match(/\(([^)]+)\)/);
      if (paren) rest = paren[1].trim();
      const isTitleOrInitials =
        /^(Abp|Abp\.|Bp|Patr|Patriarch|Metr|Metropolitan|Saint|St\.|King|Queen|Emperor|Tsar|Prince|Graf)\b/i.test(rest) ||
        /^([A-Z]\.\s*)+$/.test(rest);
      if (rest && !isTitleOrInitials) return `${rest} ${sur}`;
      return rest ? `${sur} (${rest})` : sur;
    }
    return base2;
  }
  return q.n;
};

// Normalize LC transliteration: ligatures, soft signs, combining breve
const normLC = (s) => String(s)
  .replace(/[︠︡]/g, '')
  .replace(/[ʹʺ'']/g, '')
  .replace(/\u0306/g, '')   // combining breve (i̊ → i in LC -skyĭ)
  .replace(/\u012d/g, '')   // precomposed ĭ fallback
  .replace(/i\u0361/g, 'i')
  .replace(/u\u0361/g, 'u')
  .toLowerCase();

function bioOf(q, groups, uk) {
  const gLabel = (groups && groups[q.g]) || q.g || '';
  const today  = (y) => (y >= 2026 ? (uk ? 'сьогодні' : 'today') : Math.floor(y));
  const seq = [];
  q.s.forEach((x) => {
    const nm = x[0].split(' / ')[0], last = seq[seq.length - 1];
    if (last && last.n === nm) last.to = Math.max(last.to, x[4]);
    else seq.push({ n: nm, from: x[3], to: x[4], approx: x[5] });
  });
  const places = seq.map((x) =>
    `${x.n} ${Math.floor(x.from)}${x.to > x.from + 0.5 ? '–' + today(x.to) : ''}${x.approx ? '*' : ''}`
  ).join(', ');
  const approx = seq.some((x) => x.approx) ? (uk ? ' * приблизно.' : ' * approximate.') : '';
  const bkNote = uk
    ? `${q.bk} ${q.bk === 1 ? 'книжка' : q.bk < 5 ? 'книжки' : 'книжок'} про цю особу в колекції.`
    : `${q.bk} book${q.bk === 1 ? '' : 's'} about this person in the collection.`;
  return `${gLabel} (${fmtY(q.b, uk)}–${q.d == null ? (uk ? 'сьогодні' : 'present') : fmtY(q.d, uk)}). ${places}.${approx} ${bkNote}${q.bio ? ' ' + q.bio : ''}`;
}

const btn = {
  font: 'inherit', fontSize: 13, padding: '3px 10px', cursor: 'pointer',
  background: 'transparent', border: '1px solid var(--border, rgba(255,255,255,0.18))',
  borderRadius: 5, color: 'inherit',
};

const pplUk = (n) => n === 1 ? 'особа' : n < 5 ? 'особи' : 'осіб';

export default function Lifepaths() {
  const world = useWorld();
  const { language, tr } = useLocale();
  const uk = language === 'uk';
  const L  = tr;

  // ── all state at the top ──────────────────────────────────────────────────
  const [lp,        setLp]        = useState(null);
  const [geo,       setGeo]       = useState(null);
  const [gw,        setGw]        = useState(null);
  const [idx,       setIdx]       = useState(1918 - YEAR_MIN);
  const [play,      setPlay]      = useState(false);
  const [speed,     setSpeed]     = useState(400);
  const speedRef   = useRef(400);
  const timerRef   = useRef(null);

  const year = YEAR_MIN + idx;

  useEffect(() => { speedRef.current = speed; }, [speed]);

  // Interval-based play — flushSync forces React 18 to paint each tick immediately
  useEffect(() => {
    if (!play) return undefined;
    timerRef.current = setInterval(() => {
      flushSync(() => {
        setIdx((i) => (i >= N_YEARS ? i : i + 1));
      });
    }, speedRef.current);
    return () => clearInterval(timerRef.current);
  }, [play]);

  // Stop when end reached
  useEffect(() => {
    if (play && idx >= N_YEARS) setPlay(false);
  }, [play, idx]);

  const [selGroup,  setSelGroup]  = useState('');
  const [minBk,     setMinBk]     = useState(0);
  const [focus,     setFocus]     = useState(null);
  const [showMoves, setShowMoves] = useState(true);
  const [showBooks, setShowBooks] = useState(false);

  // ── data loading ──────────────────────────────────────────────────────────
  useEffect(() => {
    get('anim_people.json').then(setLp).catch(() => setLp({ groups: {}, people: [] }));
    get('ukraine-independent-outline.geojson').then(setGeo).catch(() => setGeo(null));
  }, []);

  useEffect(() => {
    if (showBooks && focus && !gw) {
      get('geo_workbench.json').then(setGw).catch(() => setGw({ records: [] }));
    }
  }, [showBooks, focus, gw]);

  // ── derived data ──────────────────────────────────────────────────────────
  const people   = useMemo(() => (lp ? lp.people : []), [lp]);
  const groups   = useMemo(() => (lp ? lp.groups : {}), [lp]);
  const filtered = useMemo(
    () => people.filter((q) => (!selGroup || q.g === selGroup) && (q.bk || 0) >= minBk),
    [people, selGroup, minBk],
  );

  const nowMap = useMemo(() => {
    const m = new Map();
    filtered.forEach((q) => {
      if (year < Math.floor(q.b) || (q.d != null && year > q.d + 0.01)) return;
      let cur = null;
      for (let k = 0; k < q.s.length; k++) {
        const x = q.s[k], nx = q.s[k + 1];
        if (x[3] <= year + 1e-9 && (year < x[4] || (nx ? year < nx[3] && nx[3] - x[4] <= 1.5 : q.d == null && year >= x[4] - 1e-9))) {
          cur = x; break;
        }
      }
      if (cur) m.set(q.n, { q, stay: cur });
    });
    return m;
  }, [filtered, year]);

  const moves = useMemo(() => {
    if (!showMoves) return [];
    const source = focus ? filtered.filter((q) => q.n === focus) : filtered;
    const out = [];
    source.forEach((q) => {
      if (year < Math.floor(q.b) || (q.d != null && year > q.d + 0.01)) return;
      for (let k = 1; k < q.s.length; k++) {
        const a = q.s[k - 1], b = q.s[k];
        if (b[3] <= year + 1e-9 && (a[1] !== b[1] || a[2] !== b[2])) out.push({ q, a, b });
      }
    });
    return out;
  }, [filtered, year, focus, showMoves]);

  const nowList     = useMemo(() => [...nowMap.values()].sort((a, b) => (b.q.bk || 0) - (a.q.bk || 0)), [nowMap]);
  const focusPerson = focus ? people.find((q) => q.n === focus) : null;

  const { books, lcHeading } = useMemo(() => {
    if (!focusPerson || !gw) return { books: null, lcHeading: null };
    const key = normLC(focusPerson.n);
    if (key.length < 4) return { books: [], lcHeading: null };
    // Strip trailing 'i' before comma to match -skyi (LC) vs -sky (stored)
    const normSub = (s) => normLC(s).replace(/i(?=,|$)/, '');
    const normKey = key.replace(/i(?=,|$)/, '');
    let heading = null;
    const matched = (gw.records || [])
      .filter((r) => {
        const subjects = Array.isArray(r.h) ? r.h : [String(r.h || '')];
        const match = subjects.find((s) => {
          const n = normSub(s);
          return n.startsWith(normKey + ',') || n.startsWith(normKey + ' ');
        });
        if (match && !heading) heading = match;
        return !!match;
      })
      .map((r) => ({ id: r.i, year: r.y, title: r.t, place: r.p, langs: r.l }))
      .sort((a, b) => (a.year || 9999) - (b.year || 9999));
    return { books: matched, lcHeading: heading };
  }, [focusPerson, gw]);

  const notPresent = useMemo(
    () => filtered.filter((q) => !nowMap.has(q.n)).sort((a, b) => (b.bk || 0) - (a.bk || 0)),
    [filtered, nowMap],
  );

  // ── render ────────────────────────────────────────────────────────────────
  return (
    <div style={{ padding: '0 12px', maxWidth: 1280, boxSizing: 'border-box' }}>
      <h2 style={{ margin: '4px 0 2px', fontSize: 18 }}>{L('Lifepaths in motion')}</h2>
      <p className="tl-muted" style={{ fontSize: 13, margin: '0 0 8px', maxWidth: 820 }}>
        {L('People from the Ukrainian-history catalogue, placed where they lived and worked in each year. Press play, or drag the year slider. Scroll to zoom the map, drag to pan. Click a name to follow one person; click again to clear.')}
      </p>

      {/* Row 1: play + slider */}
      <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 6 }}>
        <button style={{ ...btn, fontWeight: 700, minWidth: 68 }}
          onClick={() => {
            if (!play && idx >= N_YEARS) setIdx(0);
            setPlay((p) => !p);
          }}>
          {play ? L('Pause') : L('Play')}
        </button>
        <button style={btn} onClick={() => { setPlay(false); setIdx((i) => Math.max(0, i - 10)); }}>
          −10 {uk ? 'р.' : 'yr'}
        </button>
        <button style={btn} onClick={() => { setPlay(false); setIdx((i) => Math.min(N_YEARS, i + 10)); }}>
          +10 {uk ? 'р.' : 'yr'}
        </button>
        <input
          type="range"
          min="0"
          max={N_YEARS}
          value={idx}
          onChange={(e) => { setPlay(false); setIdx(+e.target.value); }}
          style={{ flex: '1 1 0', minWidth: 0 }}
          aria-label={uk ? 'рік' : 'year'}
        />
        <b style={{ fontSize: 22, minWidth: 56, textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: '#9cc7f0' }}>
          {year}
        </b>
      </div>

      {/* Row 2: filters */}
      <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', marginBottom: 8 }}>
        <label style={{ fontSize: 13 }}>
          {L('Speed')}{' '}
          <select value={speed} onChange={(e) => setSpeed(+e.target.value)} style={{ font: 'inherit', fontSize: 13 }}>
            <option value={400}>{L('Slow')}</option>
            <option value={120}>{L('Normal')}</option>
            <option value={40}>{L('Fast')}</option>
          </select>
        </label>
        <label style={{ fontSize: 13 }}>
          {L('Group')}{' '}
          <select value={selGroup} onChange={(e) => setSelGroup(e.target.value)} style={{ font: 'inherit', fontSize: 13 }}>
            <option value="">{L('all groups')}</option>
            {Object.entries(groups).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
          </select>
        </label>
        <label style={{ fontSize: 13 }}>
          {uk ? 'Мін. книжок' : 'Min books'}{' '}
          <select value={minBk} onChange={(e) => setMinBk(+e.target.value)} style={{ font: 'inherit', fontSize: 13 }}>
            {[[0, uk ? 'будь-яка' : 'Any'], [2, '2+'], [5, '5+'], [10, '10+'], [20, '20+']].map(([v, l]) =>
              <option key={v} value={v}>{l}</option>)}
          </select>
        </label>
        <label style={{ fontSize: 13 }}>
          <input type="checkbox" checked={showMoves} onChange={(e) => setShowMoves(e.target.checked)} />
          {' '}{L('moves')}
        </label>
        {focus && (
          <button style={{ ...btn, color: '#9cc7f0' }} onClick={() => { setFocus(null); setShowBooks(false); }}>
            {L('Clear')}
          </button>
        )}
      </div>

      {/* Legend */}
      <div style={{ display: 'flex', gap: 14, flexWrap: 'wrap', fontSize: 12.5, marginBottom: 6, opacity: 0.8 }}>
        {Object.entries(groups).map(([k, v]) => (
          <span key={k}>
            <span style={{ display: 'inline-block', width: 10, height: 10, borderRadius: '50%', background: GC[k] || '#999', marginRight: 4, verticalAlign: -1 }} />
            {v}
          </span>
        ))}
        <span className="tl-muted">
          · {uk ? 'закрашений = відоме місце' : 'filled = known place'}
          · {uk ? 'порожній = приблизно' : 'open = approximate'}
          · {uk ? 'товщина лінії = книжки' : 'line width = books'}
        </span>
      </div>

      {/* Main layout */}
      <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap', alignItems: 'flex-start' }}>

        {/* Map */}
        <div style={{ flex: '1 1 540px', minWidth: 300 }}>
          {!world || !lp
            ? <p className="tl-muted" style={{ padding: 24 }}>{L('Loading…')}</p>
            : (
              <ZoomMap world={world} geo={geo} start="Europe" label={`${uk ? 'Життєві шляхи' : 'Lifepaths'} ${year}`}>
                {(u, P) => (
                  <g>
                    {moves.map(({ q, a, b }, k) => {
                      const [ax, ay] = P(a[1], a[2]), [bx, by] = P(b[1], b[2]);
                      const opacity = focus && focus !== q.n ? 0.06 : Math.max(0.15, 0.85 - (year - b[3]) / 60);
                      return (
                        <line key={k} x1={ax} y1={ay} x2={bx} y2={by}
                          stroke={GC[q.g] || '#b3bac2'}
                          strokeWidth={(0.9 + Math.min(2.2, (q.bk || 0) / 14)) * u}
                          strokeLinecap="round" opacity={opacity}
                          style={{ pointerEvents: 'none' }}>
                          <title>{`${fullName(q)}: ${a[0]} → ${b[0]}`}</title>
                        </line>
                      );
                    })}
                    {nowList.map(({ q, stay }) => {
                      const [x, y2] = P(stay[1], stay[2]);
                      const col = GC[q.g] || '#b3bac2';
                      const approx    = stay[5] === 1;
                      const isFocused = focus === q.n;
                      const r         = (isFocused ? 6.5 : 4.2) * u;
                      const showLabel = nowList.length <= 28 || (q.bk || 0) >= 10 || isFocused;
                      return (
                        <g key={q.n} onClick={() => setFocus(focus === q.n ? null : q.n)}
                          style={{ cursor: 'pointer' }} opacity={focus && !isFocused ? 0.22 : 1}>
                          <circle cx={x} cy={y2} r={r}
                            fill={approx ? 'rgba(14,18,24,0.85)' : col} stroke={col}
                            strokeWidth={(isFocused ? 2.2 : 1.4) * u} />
                          {showLabel && (
                            <text x={x + r + 2 * u} y={y2 + 4 * u} fontSize={11 * u}
                              fontWeight={isFocused ? 700 : 500} fill="#f0f3f8"
                              stroke="rgba(14,18,24,0.88)" strokeWidth={3 * u} paintOrder="stroke"
                              style={{ pointerEvents: 'none' }}>
                              {fullName(q)}
                            </text>
                          )}
                          <title>{`${fullName(q)} (${fmtY(q.b, uk)}–${q.d == null ? (uk ? 'сьогодні' : 'present') : fmtY(q.d, uk)}) · ${stay[0]} · ${q.bk} ${uk ? 'кн.' : 'books'}`}</title>
                        </g>
                      );
                    })}
                  </g>
                )}
              </ZoomMap>
            )}
          <div className="tl-muted" style={{ fontSize: 11.5, marginTop: 4 }}>
            {nowMap.size} {uk ? pplUk(nowMap.size) : (nowMap.size === 1 ? 'person' : 'people')} {uk ? 'у' : 'present in'} {year}.
            {' '}{uk ? 'Місця поза картою розташовані на її краю.' : 'Places outside the view sit on the map edge.'}
          </div>
        </div>

        {/* Sidebar */}
        <div style={{ flex: '1 1 280px', minWidth: 260, maxWidth: 400 }}>

          {/* Bio panel */}
          {focusPerson && (
            <div style={{ border: '1px solid var(--border, rgba(255,255,255,0.18))', borderRadius: 8, padding: '10px 12px', marginBottom: 12, background: 'rgba(255,255,255,0.03)' }}>
              <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, marginBottom: 4 }}>
                <span style={{ display: 'inline-block', width: 12, height: 12, borderRadius: '50%', background: GC[focusPerson.g] || '#999', flex: 'none' }} />
                <b style={{ fontSize: 15 }}>{fullName(focusPerson, lcHeading)}</b>
                <button style={{ ...btn, marginLeft: 'auto', fontSize: 11, padding: '1px 6px' }}
                  onClick={() => { setFocus(null); setShowBooks(false); }}>×</button>
              </div>
              <p style={{ fontSize: 13, margin: '0 0 8px', lineHeight: 1.55 }}>
                {bioOf(focusPerson, groups, uk)}
              </p>

              {/* Lifepath timeline */}
              <div style={{ fontSize: 12.5, marginBottom: 10 }}>
                <b>{uk ? 'Життєвий шлях' : 'Lifepath'}</b>
                {focusPerson.s.map((x, k) => {
                  const active = year >= x[3] && year < x[4];
                  return (
                    <div key={k} style={{ padding: '2px 0', opacity: active ? 1 : 0.45, fontWeight: active ? 600 : 400, fontSize: 12 }}>
                      <span style={{ fontVariantNumeric: 'tabular-nums', opacity: 0.65, marginRight: 8 }}>
                        {Math.floor(x[3])}–{x[4] >= 2026 ? (uk ? 'сьогодні' : 'today') : Math.floor(x[4])}
                      </span>
                      {x[0]}{x[5] === 1 && <span className="tl-muted"> *</span>}
                    </div>
                  );
                })}
              </div>

              {/* Books toggle */}
              <button style={{ ...btn, fontSize: 12 }} onClick={() => setShowBooks((v) => !v)}>
                {showBooks
                  ? (uk ? 'Сховати книжки' : 'Hide books')
                  : `${uk ? 'Показати книжки' : 'Show books'} (${focusPerson.bk})`}
              </button>

              {showBooks && (
                <div style={{ marginTop: 8 }}>
                  {!gw && <p className="tl-muted" style={{ fontSize: 12 }}>{L('Loading…')}</p>}
                  {gw && !books && <p className="tl-muted" style={{ fontSize: 12 }}>{uk ? 'Пошук…' : 'Searching…'}</p>}
                  {books && books.length === 0 && (
                    <p className="tl-muted" style={{ fontSize: 12 }}>
                      {uk ? `Записів для «${focusPerson.n}» не знайдено.` : `No records found for "${focusPerson.n}".`}
                    </p>
                  )}
                  {books && books.map((r) => (
                    <div key={r.id} style={{ fontSize: 12.5, margin: '6px 0', lineHeight: 1.4, borderBottom: '1px solid rgba(255,255,255,0.07)', paddingBottom: 5 }}>
                      <div>
                        <span style={{ opacity: 0.55, fontVariantNumeric: 'tabular-nums', marginRight: 6 }}>{r.year || '—'}</span>
                        {/^\d+$/.test(r.id)
                          ? <a href={`https://lccn.loc.gov/${r.id}`} target="_blank" rel="noreferrer" style={{ color: '#9cc7f0' }}>{r.title}</a>
                          : r.title}
                      </div>
                      {(r.place || r.langs) && (
                        <div className="tl-muted" style={{ fontSize: 11.5 }}>
                          {r.place}{r.langs ? ` · ${Array.isArray(r.langs) ? r.langs.join(', ') : r.langs}` : ''}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Present list */}
          <div style={{ fontSize: 13 }}>
            <div className="tl-muted" style={{ marginBottom: 4, fontSize: 12 }}>
              {nowList.length > 0
                ? `${nowList.length} ${uk ? pplUk(nowList.length) : (nowList.length === 1 ? 'person' : 'people')} ${uk ? 'у' : 'in'} ${year}`
                : (uk ? 'Нікого в цій групі у цьому році.' : 'No one in this group for this year.')}
            </div>
            {nowList.map(({ q, stay }) => (
              <div key={q.n}
                onClick={() => { setFocus(focus === q.n ? null : q.n); setShowBooks(false); }}
                style={{ display: 'flex', alignItems: 'baseline', gap: 7, padding: '3px 5px', borderRadius: 5, cursor: 'pointer',
                  fontWeight: focus === q.n ? 700 : 400,
                  background: focus === q.n ? 'rgba(255,255,255,0.1)' : 'transparent',
                  opacity: focus && focus !== q.n ? 0.4 : 1 }}>
                <span style={{ width: 9, height: 9, borderRadius: '50%', flex: 'none', background: GC[q.g] || '#999',
                  border: stay[5] === 1 ? `2px solid ${GC[q.g] || '#999'}` : 'none', boxSizing: 'border-box' }} />
                <span style={{ flex: 1 }}>{fullName(q)}</span>
                <span className="tl-muted" style={{ fontSize: 11.5, whiteSpace: 'nowrap' }}>{stay[0].split(' / ')[0]}</span>
                <span className="tl-muted" style={{ fontSize: 11, minWidth: 26, textAlign: 'right' }}>{q.bk}</span>
              </div>
            ))}

            {notPresent.length > 0 && (
              <details style={{ marginTop: 10 }}>
                <summary className="tl-muted" style={{ fontSize: 12, cursor: 'pointer' }}>
                  {notPresent.length} {uk ? (notPresent.length === 1 ? 'особа' : 'осіб') : (notPresent.length === 1 ? 'person' : 'people')} {uk ? 'не в цьому році' : `not present in ${year}`}
                </summary>
                <div style={{ marginTop: 4 }}>
                  {notPresent.map((q) => (
                    <div key={q.n}
                      onClick={() => { setFocus(focus === q.n ? null : q.n); setShowBooks(false); }}
                      style={{ display: 'flex', gap: 7, alignItems: 'baseline', padding: '2px 5px', borderRadius: 5, cursor: 'pointer',
                        fontWeight: focus === q.n ? 600 : 400,
                        background: focus === q.n ? 'rgba(255,255,255,0.08)' : 'transparent',
                        opacity: 0.5, fontSize: 12.5 }}>
                      <span style={{ width: 8, height: 8, borderRadius: '50%', flex: 'none', background: GC[q.g] || '#999' }} />
                      <span style={{ flex: 1 }}>{fullName(q)}</span>
                      <span className="tl-muted" style={{ fontSize: 11 }}>{fmtY(q.b, uk)}–{q.d == null ? '…' : fmtY(q.d, uk)}</span>
                      <span className="tl-muted" style={{ fontSize: 11, minWidth: 26, textAlign: 'right' }}>{q.bk}</span>
                    </div>
                  ))}
                </div>
              </details>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
