// Logic of the Records page: the places and times a record ends up with once your edits are applied, and the vector of anything that has places.
// The same rules are in paper_pipeline/geo_edits.py (keep them in step): that is how your edits reach the paper's numbers.

export const EMPTY = { version: 1, records: {}, newRecords: {}, entities: {}, gazetteer: { places: [], times: [], polities: {} } };
export const THE_UKRAINE = /\bthe Ukraine\b/i;      // an English text that says "the Ukraine" means Soviet Ukraine (rule given by the author)
export const norm = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ︠-︯]/g, '').replace(/[^a-z0-9а-яіїєґ]+/g, ' ').trim();
export const span = (s, e) => (s == null && e == null ? 'no dates' : s === e || e == null ? `${yr(s)}` : `${s == null ? '?' : yr(s)}–${yr(e)}`);
export const yr = (v) => (v == null ? '?' : Math.floor(v));

// polities with your overrides and additions
export function mergedPolities(wb, ed) {
  const ov = (ed.gazetteer && ed.gazetteer.polities) || {};
  const list = wb.polities.map((p) => ov[p.id] || p);
  Object.values(ov).forEach((p) => { if (!wb.polities.some((q) => q.id === p.id)) list.push(p); });
  return list;
}
// cells (and extra points) of a polity within the years [s, e]: every phase that overlaps them (all phases when the years are unknown)
export function polityCells(p, s, e) {
  const phases = p.phases.filter((ph) => !ph.claimed && (s == null && e == null ? true : (ph.start <= (e == null ? s : e) + 0.999 && ph.end >= (s == null ? e : s))));
  const use = phases.length ? phases : p.phases.filter((ph) => !ph.claimed);
  const set = new Set(); use.forEach((ph) => ph.cells.forEach((c) => set.add(c)));
  return { cells: [...set], extra: p.extra || [], phases: use };
}
// weighted points of one place item: [lat, lon, weight] (a polity spreads weight 1 equally over its cells and extra points)
export function itemPoints(it, wb, pol) {
  if (it.polity && pol[it.polity]) {
    const { cells, extra } = polityCells(pol[it.polity], it.start, it.end);
    const tot = cells.length + extra.reduce((s, x) => s + (x.w || 1), 0);
    if (!tot) return [];
    const k = it.w == null ? 1 : it.w;   // optional weight of the item (the event assignments split a record over several states)
    return [...cells.map((c) => [wb.grid.cells[c][0], wb.grid.cells[c][1], k / tot]), ...extra.map((x) => [x.lat, x.lon, (k * (x.w || 1)) / tot])];
  }
  return it.lat == null || it.lon == null ? [] : [[it.lat, it.lon, 1]];
}

// the places and times of a record after your edits.  Each item: key, src (dataset | rule | added | entity), label, lat, lon, start, end, polity, map, deleted, edited
export function effItems(rec, ed, wb, pol, entLabels) {
  const re = (ed.records || {})[rec.i] || {}, items = [];
  rec.a.forEach((a, k) => {
    const o = (re.about || {})[k] || {};
    items.push({ key: 'd' + k, src: 'dataset', label: o.label ?? a[0], lat: o.lat !== undefined ? o.lat : a[3], lon: o.lon !== undefined ? o.lon : a[4], start: o.start !== undefined ? o.start : a[1], end: o.end !== undefined ? o.end : a[2],
      polity: o.polity || null, map: o.map !== false, deleted: !!o.deleted, edited: Object.keys(o).length > 0, orig: a });
  });
  const off = re.rulesOff || [];
  if ((THE_UKRAINE.test(rec.t) || rec.h.some((h) => THE_UKRAINE.test(h))) && pol.ussr) {
    // the years of the rule: those of the dated "Ukraine" items of the record, within the life of Soviet Ukraine (1919-1991); all of them when there are none
    const d = items.filter((x) => !x.deleted && /^ukraine\b/i.test(x.label) && (x.start != null || x.end != null));
    const s0 = d.length ? Math.max(1919, Math.min(...d.map((x) => (x.start != null ? x.start : x.end)))) : 1919, e0 = d.length ? Math.min(1991, Math.max(...d.map((x) => (x.end != null ? x.end : x.start)))) : 1991;
    items.push({ key: 'r:the-ukraine', src: 'rule', label: 'Soviet Ukraine (rule: the text says “the Ukraine”)', polity: 'ussr', start: s0 <= e0 ? s0 : 1919, end: s0 <= e0 ? e0 : 1991, map: true, deleted: off.includes('the-ukraine') });
  }
  (re.add || []).forEach((x, k) => items.push({ key: 'a' + k, src: 'added', map: x.map !== false, deleted: false, ...x }));
  (entLinks(rec, ed)).forEach(({ e, inherit }) => {
    if (!inherit) return;
    const E = (ed.entities || {})[e]; if (!E) return;
    (E.places || []).forEach((x, k) => items.push({ key: `e:${e}:${k}`, src: 'entity', map: x.map !== false, deleted: false, ...x, label: `${e}: ${x.label}` }));
  });
  return items;
}
// entities of a record: those of its headings (not inherited unless you tick inherit) and those you linked
export function entLinks(rec, ed) {
  const re = (ed.records || {})[rec.i] || {}, un = re.unlink || [];
  const own = (rec.eLabels || []).filter((l) => !un.includes(l)).map((l) => ({ e: l, inherit: ((re.link || []).find((x) => x.e === l) || {}).inherit === true, own: true }));
  const more = (re.link || []).filter((x) => !(rec.eLabels || []).includes(x.e)).map((x) => ({ e: x.e, inherit: !!x.inherit, own: false }));
  return [...own, ...more];
}
export const mapPoints = (items, wb, pol) => items.filter((x) => x.map && !x.deleted).flatMap((x) => itemPoints(x, wb, pol));

// ---- standard deviational ellipse (as paper_pipeline/common.sde): median centre, 85% core, covariance, signed nowhere ----
const wq = (v, w, q) => { const o = v.map((_, i) => i).sort((a, b) => v[a] - v[b]); let c = 0; const tot = w.reduce((s, x) => s + x, 0); for (const i of o) { c += w[i]; if (c >= tot * q - 1e-12) return v[i]; } return v[o[o.length - 1]]; };
export function sde(pts, trim = 0.85) {
  const P = pts.filter((p) => p[2] > 0); if (P.length < 3) return null;
  const lat = P.map((p) => p[0]), lon = P.map((p) => p[1]), w = P.map((p) => p[2]);
  const la0 = wq(lat, w, 0.5), lo0 = wq(lon, w, 0.5), k = Math.cos((la0 * Math.PI) / 180) * 111.32;
  const x = lon.map((v) => (v - lo0) * k), y = lat.map((v) => (v - la0) * 110.57), r = x.map((v, i) => Math.hypot(v, y[i]));
  const lim = Math.max(wq(r, w, trim), 1e-6), idx = r.map((v, i) => (v <= lim ? i : -1)).filter((i) => i >= 0);
  if (idx.length < 3) return null;
  const sw = idx.reduce((s, i) => s + w[i], 0), mx = idx.reduce((s, i) => s + w[i] * x[i], 0) / sw, my = idx.reduce((s, i) => s + w[i] * y[i], 0) / sw;
  let sxx = 0, syy = 0, sxy = 0; idx.forEach((i) => { const dx = x[i] - mx, dy = y[i] - my; sxx += w[i] * dx * dx; syy += w[i] * dy * dy; sxy += w[i] * dx * dy; });
  sxx /= sw; syy /= sw; sxy /= sw;
  const tr = sxx + syy, dt = sxx * syy - sxy * sxy, d = Math.sqrt(Math.max(tr * tr / 4 - dt, 0)), l1 = Math.max(tr / 2 + d, 1), l2 = Math.max(tr / 2 - d, 1);
  const th = 0.5 * Math.atan2(2 * sxy, sxx - syy);               // angle of the long axis from east, counter-clockwise
  const a = Math.sqrt(l1), b = Math.sqrt(l2);
  return { lat: la0 + my / 110.57, lon: lo0 + mx / k, a, b, elong: a / b, bearing: (((90 - (th * 180) / Math.PI) % 180) + 180) % 180 };
}
export function ellipsePath(v, n = 48) {            // [[lat, lon], ...] of the ellipse of a vector
  const t = (v.bearing * Math.PI) / 180, out = [], k = Math.cos((v.lat * Math.PI) / 180) * 111.32;
  for (let i = 0; i < n; i++) {
    const q = (i / n) * 2 * Math.PI, al = v.a * Math.cos(q), ac = v.b * Math.sin(q);
    out.push([v.lat + (al * Math.cos(t) - ac * Math.sin(t)) / 110.57, v.lon + (al * Math.sin(t) + ac * Math.cos(t)) / k]);
  }
  return out;
}
export const bearingName = (b) => ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE', 'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW'][Math.round(b / 22.5) % 16];

// ---- Wikidata look-up (suggestions only; nothing is saved until you press a button) -------------------------------------------------
const WD = 'https://www.wikidata.org/w/api.php';
const wd = (q) => fetch(`${WD}?${new URLSearchParams({ format: 'json', origin: '*', ...q })}`).then((r) => r.json());
const claim = (E, p) => { const c = (E.claims || {})[p]; return c && c[0] && c[0].mainsnak && c[0].mainsnak.datavalue ? c[0].mainsnak.datavalue.value : null; };
const yearOf = (E, p) => { const v = claim(E, p); const m = v && v.time && /([+-]\d{4})/.exec(v.time); return m ? parseInt(m[1], 10) : null; };
export async function wdLookup(text, lang = 'en') {
  const s = await wd({ action: 'wbsearchentities', search: text, language: lang, uselang: lang, limit: '6', type: 'item' });
  const ids = (s.search || []).map((x) => x.id); if (!ids.length) return [];
  const g = await wd({ action: 'wbgetentities', ids: ids.join('|'), props: 'claims|labels|descriptions|sitelinks/urls', languages: `${lang}|en|uk` });
  const ents = ids.map((i) => g.entities[i]).filter(Boolean);
  const refIds = [...new Set(ents.flatMap((E) => [claim(E, 'P19'), claim(E, 'P20')]).filter(Boolean).map((v) => v.id))];
  const refs = refIds.length ? (await wd({ action: 'wbgetentities', ids: refIds.join('|'), props: 'claims|labels', languages: `${lang}|en` })).entities : {};
  const place = (v) => { if (!v) return null; const E = refs[v.id]; const c = E && claim(E, 'P625'); return c ? { label: ((E.labels || {})[lang] || (E.labels || {}).en || {}).value || v.id, lat: c.latitude, lon: c.longitude } : null; };
  return ents.map((E) => {
    const c = claim(E, 'P625'), lab = ((E.labels || {})[lang] || (E.labels || {}).en || {}).value || E.id;
    const sl = (E.sitelinks || {}); const link = (sl[lang + 'wiki'] || sl.enwiki || sl.ukwiki || {}).url || `https://www.wikidata.org/wiki/${E.id}`;
    return { id: E.id, label: lab, desc: ((E.descriptions || {})[lang] || (E.descriptions || {}).en || {}).value || '', lat: c ? c.latitude : null, lon: c ? c.longitude : null, wiki: link,
      born: yearOf(E, 'P569'), died: yearOf(E, 'P570'), birthPlace: place(claim(E, 'P19')), deathPlace: place(claim(E, 'P20')) };
  });
}
