import * as d3 from 'd3';

// The "Temporal aboutness" timeline of the map: the same design as the Time page -- a shape showing how many records
// are about each moment, a non-linear time axis (older periods compressed), a brush to choose the range, and the
// periods that shaped Ukraine in lanes underneath (they overlap, so each kind has its own lane).
// It drives the existing aboutMin / aboutMax sliders (kept in the page, hidden), so everything that follows the
// slider (map layer, sunburst, play button, label, keyword search) keeps working unchanged.
const BRK = [-3000, 800, 1400, 1648, 1800, 1917, 1991, 2030];
const FR = [0, 0.1, 0.24, 0.37, 0.56, 0.75, 0.92, 1];
const ERAS = [
  [-3000, 882, 'Antiquity', '#c9b79c', 0], [882, 1240, 'Kyivan Rus', '#b8564a', 0], [1240, 1349, 'Galicia–Volhynia', '#a86f3c', 0],
  [1490, 1775, 'Cossack era', '#d9b26a', 0], [1917, 1922, 'Revolution', '#d46a6a', 0], [1922, 1991, 'Soviet era', '#a05a5a', 0], [1991, 2030, 'Independence', '#4a86c8', 0],
  [1349, 1569, 'Kingdom of Poland (Galicia)', '#c9a14a', 1], [1569, 1795, 'Rzeczpospolita (Polish–Lithuanian Commonwealth)', '#e0c060', 1],
  [1362, 1569, 'Lithuanian rule (Grand Duchy of Lithuania)', '#6fa0d8', 2], [1772, 1918, 'Habsburg monarchy', '#9b7fd0', 2],
  [1721, 1917, 'Russian Empire', '#5aa9a0', 3], [1441, 1783, 'Crimean Khanate', '#d78b52', 4],
];
export const ABOUT_PERIODS = ERAS.map(([s, e, name]) => ({ s, e, name }));
const LANE_H = 14, LANES = 5, SH = 74;

export function initAboutTimeline({ DATA, host, minInput, maxInput, warp }) {
  if (!host) return () => {};
  const toU = d3.scaleLinear().domain(BRK).range(FR).clamp(true);
  // how many records are about each moment (a record counts once however many places and dates it has)
  const S = 240, cnt = new Array(S).fill(0);
  for (const r of DATA.records) {
    const hit = new Uint8Array(S);
    for (const m of r.about) {
      if (m.s == null || m.e == null) continue;
      const a = Math.max(0, Math.floor(toU(m.s) * S)), e = Math.min(S - 1, Math.floor(toU(m.e) * S));
      for (let k = a; k <= e; k++) hit[k] = 1;
    }
    for (let k = 0; k < S; k++) cnt[k] += hit[k];
  }
  const yMin = DATA.aboutYearMin, yMax = DATA.aboutYearMax;
  let svg, brush, bg, iw = 300, busy = false;
  const setInputs = (y0, y1) => {
    busy = true;
    minInput.value = Math.round(warp.toWarp(Math.max(yMin, y0)));
    maxInput.value = Math.round(warp.toWarp(Math.min(yMax, y1)));
    // Update both ends before notifying the range controls. Dispatching after
    // setting the first end let its old opposite end clamp later periods back
    // into the previous range.
    maxInput.dispatchEvent(new Event('input')); // updates the label, map, network and sunburst
    busy = false;
  };
  const readInputs = () => [warp.toYear(parseInt(minInput.value, 10)), warp.toYear(parseInt(maxInput.value, 10))];
  const moveBrush = () => {
    if (!bg) return;
    const [a, b] = readInputs(); busy = true;
    bg.call(brush.move, [toU(a) * iw, toU(b) * iw]);
    busy = false;
  };
  const draw = () => {
    const W = Math.max(240, host.clientWidth || 320), ML = 4, MR = 4; iw = W - ML - MR;
    host.innerHTML = '';
    svg = d3.select(host).append('svg').attr('width', W).attr('height', SH + 18 + LANES * LANE_H + 4).style('display', 'block').style('color', '#c8cdd4');
    const g = svg.append('g').attr('transform', `translate(${ML},0)`);
    const x = (y) => toU(y) * iw;
    ERAS.forEach(([a, b, name, col]) => g.append('rect').attr('x', x(a)).attr('y', 0).attr('width', Math.max(1, x(b) - x(a))).attr('height', SH).attr('fill', col).attr('opacity', 0.11));
    const mx = d3.max(cnt) || 1, ys = d3.scaleLinear().domain([-mx / 2, mx / 2]).range([SH - 3, 3]);
    g.append('path').datum(cnt).attr('d', d3.area().x((d, k) => (k / (S - 1)) * iw).y0((d) => ys(-d / 2)).y1((d) => ys(d / 2)).curve(d3.curveBasis)).attr('fill', '#5b9de6').attr('stroke', '#c8cdd4').attr('stroke-width', 0.5);
    [800, 1400, 1648, 1800, 1917, 1991].forEach((y) => {
      g.append('line').attr('x1', x(y)).attr('x2', x(y)).attr('y1', SH).attr('y2', SH + 4).attr('stroke', 'currentColor').attr('opacity', 0.5);
      g.append('text').attr('x', Math.max(10, x(y))).attr('y', SH + 14).attr('text-anchor', 'middle').attr('font-size', 9).attr('fill', 'currentColor').attr('opacity', 0.75).text(y < 0 ? `${-y} BCE` : y);
    });
    // periods, one lane per overlapping kind: select its exact years and retrieve
    // the matching locations through the temporal-period controls.
    const lg = g.append('g').attr('transform', `translate(0,${SH + 18})`);
    ERAS.forEach(([a, b, name, col, ln]) => {
      const x1 = x(a), x2 = x(Math.min(b, 2030)), w = Math.max(1, x2 - x1 - 1);
      const yearLabel = (year) => year < 0 ? `${-year} BCE` : `${year} AD`;
      const rangeLabel = `${yearLabel(a)}–${yearLabel(b)}`;
      const selectPeriod = () => { setInputs(a, b); moveBrush(); }; // the inputs' own event is ignored while busy, so move the brush explicitly
      const eg = lg.append('g')
        .attr('role', 'button')
        .attr('tabindex', 0)
        .attr('aria-label', `Show locations for ${name}, ${rangeLabel}`)
        .style('cursor', 'pointer')
        .on('click', selectPeriod)
        .on('keydown', (event) => {
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            selectPeriod();
          }
        });
      eg.append('rect').attr('x', x1).attr('y', ln * LANE_H).attr('width', w).attr('height', LANE_H - 2).attr('fill', col).attr('opacity', 0.5).append('title').text(`${name}: ${rangeLabel} (click to show locations)`);
      if (w > 34) eg.append('text').attr('x', x1 + w / 2).attr('y', ln * LANE_H + 10).attr('text-anchor', 'middle').attr('font-size', 9).attr('fill', 'currentColor').style('pointer-events', 'none').text((w > 250 ? name : name.replace(/ \(.*\)/, '')).slice(0, Math.floor(w / 5)));
    });
    brush = d3.brushX().extent([[0, 0], [iw, SH]]).on('brush end', (ev) => {
      if (busy || !ev.selection) { if (!ev.selection && !busy) moveBrush(); return; }
      setInputs(toU.invert(ev.selection[0] / iw), toU.invert(ev.selection[1] / iw));
    });
    bg = g.append('g').call(brush);
    bg.select('.selection').attr('fill', '#4fa3ff').attr('fill-opacity', 0.18).attr('stroke', '#4fa3ff');
    moveBrush();
  };
  const onIn = () => { if (!busy) moveBrush(); };
  minInput.addEventListener('input', onIn); maxInput.addEventListener('input', onIn);
  window.addEventListener('resize', draw);
  draw();
  return () => { window.removeEventListener('resize', draw); minInput.removeEventListener('input', onIn); maxInput.removeEventListener('input', onIn); };
}
