// Named historical-region labels used by the Community Explorer's optional
// region-only view. This is a semantic filter, not polygon clipping.
// Avoid assigning generic Rus'/Ukraine records to Galicia–Volhynia just
// because their date range overlaps the polity's dates. Require an explicit
// geographic or polity signal in the record's title or LC subject headings.
const GALICIA_VOLHYNIA_EVIDENCE = /galicia|galician|galich|galits|halych|halyts|halicz|volhynia|volhynian|volyn|\u0432\u043e\u043b\u0438\u043d|\u0433\u0430\u043b\u0438\u0447|\u0433\u0430\u043b\u0438\u0446|kingdom of ruthenia|ruthenian kingdom/i;
function hasGaliciaVolhyniaEvidence(record) {
  const headings = (record.heads || []).flat().filter(Boolean);
  return GALICIA_VOLHYNIA_EVIDENCE.test([record.title || '', ...headings].join(' '));
}

