export default function TemporalMap() {
  const ref = useRef(null);

  useEffect(() => {
    let handle = null;
    let cancelled = false;
    const node = ref.current;

    if (node) {
      node.innerHTML = SKELETON_HTML;
    }

    Promise.all([
      fetch(`${process.env.PUBLIC_URL}/data/temporal_map.json`).then((res) => res.json()),
      fetch(`${process.env.PUBLIC_URL}/data/location_countries.json`).then((res) => res.json()),
      fetch(`${process.env.PUBLIC_URL}/data/time_index.json`).then((res) => res.json()),
      loadFileOverrides(),
    ])
      .then(([DATA, locationCountries, timeIndex, fileOverrides]) => {
        if (cancelled || !node) return;
        DATA.locationCountries = locationCountries;
        DATA.historicalPlacePeriods = HISTORICAL_PLACE_PERIODS;
        DATA.historicalMarkerPeriods = HISTORICAL_MARKER_PERIODS;
        DATA.historicalEntityPeriods = HISTORICAL_ENTITY_PERIODS;
        DATA.historicalEntityPeriodLabels = HISTORICAL_ENTITY_PERIOD_LABELS;
        DATA.historicalEntityPeriodDisplay = HISTORICAL_ENTITY_PERIOD_DISPLAY;
        DATA.historicalEntityNameDisplay = HISTORICAL_ENTITY_NAME_DISPLAY;
        DATA.historicalPeriodRegionLabels = HISTORICAL_PERIOD_REGION_LABELS;
        const nowY = new Date().getFullYear();
        (timeIndex.open_books || []).forEach((i) => { timeIndex.books[i][4] = nowY; });
        timeIndex.books.forEach((b) => b[10].forEach((r) => { if (r[3]) r[1] = nowY; }));
        applyOverrides(timeIndex, mergeOverrides(fileOverrides, loadLocalOverrides()));

        // Make the map's temporal-aboutness dates the same assigned ranges used by #/time.
        const assigned = new Map(timeIndex.books.filter((b) => b[10] && b[10].length).map((b) => [b[0], b[10]]));
        DATA.records = DATA.records.flatMap((record) => {
          const ranges = assigned.get(record.id);
          if (!ranges) return [];
          record.about = record.about.flatMap((mention) => {
            if (mention.g === 'Ukraine — Galicia–Volhynia (west)' && !hasGaliciaVolhyniaEvidence(record)) return [];
            const period = HISTORICAL_PLACE_PERIODS[mention.g];
            return ranges.flatMap((range) => {
              // time_index ranges are document-level, while `about` entries
              // already carry the place-specific date interval. Intersect the
              // two so a book's unrelated date range cannot leak onto every
              // place heading in that record (or onto another historical
              // territory represented by a separate `about` entry).
              const start = Math.max(
                range[0],
                mention.s == null ? range[0] : mention.s,
                period ? period[0] : range[0]
              );
              const end = Math.min(
                range[1],
                mention.e == null ? range[1] : mention.e,
                period ? period[1] - 1 : range[1]
              );
              // Prehistory (the Paleolithic to the Neolithic, millions of years back) is drawn as one dot at PREHISTORY_YEAR, before 3000 BCE.
              const s2 = Math.max(start, PREHISTORY_YEAR), e2 = Math.max(end, PREHISTORY_YEAR);
              return start <= end ? [{ ...mention, s: s2, e: e2 }] : [];
            });
          });
          return [record];
        });
        const allRanges = [...assigned.values()].flat();
        // The map's named timeline begins at 3000 BCE; older catalog outliers
        // must not stretch the slider beyond the visible historical scale.
        DATA.aboutYearMin = Math.max(PREHISTORY_YEAR, Math.min(...allRanges.map((r) => r[0])));
        // one more bar for the time before 3000 BCE, so that prehistoric records are on the timeline
        if (DATA.aboutYearMin <= PREHISTORY_YEAR) DATA.aboutHist = [{ s: PREHISTORY_YEAR, e: -3001, n: 0 }, ...DATA.aboutHist];
        DATA.aboutYearMax = nowY;
        // The timeline histogram is a visual guide; exact filtering uses the ranges above.
        DATA.aboutHist = DATA.aboutHist.map((bin) => ({
          ...bin,
          n: DATA.records.reduce((n, record) => n + (record.about.some((m) => m.s <= bin.e && m.e >= bin.s) ? 1 : 0), 0),
        }));
        handle = initTemporalMap(node, DATA);
      })
      .catch((err) => {
        console.error('Failed to load temporal_map.json', err);
      });

    return () => {
      cancelled = true;
      if (handle) handle.destroy();
      if (node) node.innerHTML = '';
    };
  }, []);

  return <div ref={ref} />;
}
