// Local homogeneity of subject headings: how alike are the headings of a book and of the books within 150 km,
// compared with two random books. Pure functions, no React. Same definition as Figure 6 of the paper:
//  - a book is placed at the mean of its located places (km on a plane: x = lon * cos(48.5 deg) * 111, y = lat * 111);
//  - the heading terms of a book are the vector; terms found in fewer than 4 books are dropped;
//  - similarity of two books = cosine of their term vectors;
//  - a book's value = (mean similarity to books 1..150 km away - mean similarity over all pairs) * 100, if it has >= 5 such books;
//  - values are smoothed on a grid with a Gaussian kernel; cells with a total weight below 3 books are left blank.

export const LON0 = 22, LON1 = 40.5, LAT0 = 44, LAT1 = 52.5;
const K = Math.cos((48.5 * Math.PI) / 180) * 111;
export const projX = (lon) => (lon - LON0) * K;
export const projY = (lat) => (LAT1 - lat) * 111;
export const MAP_W = (LON1 - LON0) * K;
export const MAP_H = (LAT1 - LAT0) * 111;

// raw: {vocab: [[label, kind]], books: [[id, title, lat, lon, pubYear, [termIdx]]]}; kind 0 = topic, 1 = place name, 2 = extra generic term
export function prepareBooks(raw) {
  const books = raw.books.map((b) => ({ id: b[0], title: b[1], lat: b[2], lon: b[3], year: b[4], terms: b[5], pile: b[6] || 0, x: b[3] * K, y: b[2] * 111 }));   // pile: 0 = a place of its own, 1 = the Ukraine pile (no clear era), 2 to 6 = the era piles
  // neighbour lists (1 km <= distance < 150 km) and same-place lists (< 1 km); positions never change
  const n = books.length;
  const near = new Array(n), same = new Array(n);
  for (let i = 0; i < n; i++) { near[i] = []; same[i] = []; }
  // Spatial hash keeps the 9,110-document Subjects 3D cohort quick to prepare.
  const cell = 150, bins = new Map();
  for (let i = 0; i < n; i++) {
    const a = books[i], gx = Math.floor(a.x / cell), gy = Math.floor(a.y / cell);
    for (let ox = -1; ox <= 1; ox++) for (let oy = -1; oy <= 1; oy++) {
      const candidates = bins.get(`${gx + ox},${gy + oy}`) || [];
      for (const j of candidates) {
        const dx = a.x - books[j].x, dy = a.y - books[j].y, d = Math.hypot(dx, dy);
        if (d < 1) { same[i].push(j); same[j].push(i); } else if (d < 150) { near[i].push(j); near[j].push(i); }
      }
    }
    const key = `${gx},${gy}`;
    if (!bins.has(key)) bins.set(key, []);
    bins.get(key).push(i);
  }
  return { books, near, same, vocab: raw.vocab };
}

function dot(a, b) { // sorted index arrays with weights: a = {t: Int32Array, w: number}
  let i = 0, j = 0, s = 0;
  const at = a.t, bt = b.t;
  while (i < at.length && j < bt.length) {
    if (at[i] === bt[j]) { s++; i++; j++; } else if (at[i] < bt[j]) i++; else j++;
  }
  return s * a.w * b.w;
}

// opts: {paper: bool, noCrimea: bool, piles: 'all' | 'noUkraine' | 'none', removed: Set(id)}
export function compute(P, opts) {
  const { books, near, vocab } = P;
  const n = books.length;
  const keepTerm = (t) => {
    const [label, kind] = vocab[t];
    if (opts.paper && kind !== 0) return false;
    if (opts.noCrimea && label === 'Crimea') return false;
    return true;
  };
  const active = new Array(n).fill(false);
  const terms = new Array(n);
  const df = new Map();
  for (let i = 0; i < n; i++) {
    if (opts.removed && opts.removed.has(books[i].id)) continue;
    if (opts.piles === 'none' && books[i].pile > 0) continue;            // leave out every pile at the centre
    if (opts.piles === 'noUkraine' && books[i].pile === 1) continue;     // leave out only the big Ukraine pile (no clear era)
    const ts = books[i].terms.filter(keepTerm);
    if (!ts.length) continue;
    terms[i] = ts; active[i] = true;
    for (const t of ts) df.set(t, (df.get(t) || 0) + 1);
  }
  const vec = new Array(n).fill(null);
  let m = 0;
  const sum = new Map();
  for (let i = 0; i < n; i++) {
    if (!active[i]) continue;
    const ts = terms[i].filter((t) => df.get(t) >= 4).sort((a, b) => a - b);
    if (!ts.length) { active[i] = false; continue; }
    const w = 1 / Math.sqrt(ts.length);
    vec[i] = { t: Int32Array.from(ts), w };
    m++;
    for (const t of ts) sum.set(t, (sum.get(t) || 0) + w);
  }
  let ss = 0;
  sum.forEach((v) => { ss += v * v; });
  const mu = m > 1 ? (ss - m) / (m * (m - 1)) : 0; // mean cosine over all pairs
  const val = new Float32Array(n).fill(NaN);
  let ok = 0;
  for (let i = 0; i < n; i++) {
    if (!active[i]) continue;
    let c = 0, s = 0;
    for (const j of near[i]) if (active[j]) { c++; s += dot(vec[i], vec[j]); }
    if (c >= 5) { val[i] = (s / c - mu) * 100; ok++; }
  }
  return { active, vec, mu, n: m, ok, val, terms, df };
}

// neighbours of book i with the most similar headings
export function neighboursOf(P, R, i, { sameToo = false, limit = 12 } = {}) {
  if (!R.active[i]) return [];
  const list = P.near[i].concat(sameToo ? P.same[i] : []);
  const out = [];
  const mine = new Set(R.vec[i].t);
  for (const j of list) {
    if (!R.active[j]) continue;
    const sim = dot(R.vec[i], R.vec[j]);
    const shared = [];
    for (const t of R.vec[j].t) if (mine.has(t)) shared.push(P.vocab[t][0]);
    const d = Math.hypot(P.books[i].x - P.books[j].x, P.books[i].y - P.books[j].y);
    out.push({ j, sim, shared, d });
  }
  out.sort((a, b) => b.sim - a.sim || a.d - b.d);
  const alike = out.filter((o) => o.sim > 0);
  return { top: alike.slice(0, limit), total: out.length, alike: alike.length };
}

// ---- smoothing onto a grid (cells of CELL km) --------------------------------------------------------------------
export const CELL = 6;
export const NX = Math.ceil(MAP_W / CELL), NY = Math.ceil(MAP_H / CELL);
export const unprojX = (x) => LON0 + x / K;
export const unprojY = (y) => LAT1 - y / 111;

// Gaussian kernel of every book with a value, built once per (book set, radius); it is separable (x factor times y factor).
export function makeKern(P, R, bw) {
  const n = P.books.length, reach = Math.ceil((3 * bw) / CELL), L = 2 * reach + 1, inv = 1 / (2 * bw * bw);
  const valid = [];
  for (let i = 0; i < n; i++) if (!Number.isNaN(R.val[i])) valid.push(i);
  const cx = new Int32Array(n), cy = new Int32Array(n), kx = new Float32Array(n * L), ky = new Float32Array(n * L);
  for (const i of valid) {
    const bx = P.books[i].x - LON0 * K, by = (LAT1 - P.books[i].lat) * 111;
    cx[i] = Math.round(bx / CELL) - reach; cy[i] = Math.round(by / CELL) - reach;
    for (let t = 0; t < L; t++) {
      const dx = (cx[i] + t + 0.5) * CELL - bx, dy = (cy[i] + t + 0.5) * CELL - by;
      kx[i * L + t] = Math.exp(-dx * dx * inv); ky[i * L + t] = Math.exp(-dy * dy * inv);
    }
  }
  const kern = { valid, cx, cy, kx, ky, L, bw };
  kern.den = applyKern(kern, null);
  return kern;
}

// sum over books of weight * vals[i] (vals null = 1): numerator (or the total weight) on the grid
export function applyKern(kern, vals) {
  const { valid, cx, cy, kx, ky, L } = kern;
  const out = new Float64Array(NX * NY);
  for (const i of valid) {
    const v = vals ? vals[i] : 1, o = i * L;
    for (let ty = 0; ty < L; ty++) {
      const gy = cy[i] + ty;
      if (gy < 0 || gy >= NY) continue;
      const wy = ky[o + ty], row = gy * NX;
      for (let tx = 0; tx < L; tx++) {
        const gx = cx[i] + tx;
        if (gx < 0 || gx >= NX) continue;
        const w = wy * kx[o + tx];
        if (w < 1e-4) continue;
        out[row + gx] += w * v;
      }
    }
  }
  return out;
}

export function smooth(P, R, bw, kernIn) {
  const kern = kernIn || makeKern(P, R, bw);
  const num = applyKern(kern, R.val), den = kern.den;
  const Z = new Float32Array(NX * NY).fill(NaN), Wt = new Float32Array(NX * NY);
  for (let k = 0; k < Z.length; k++) { Wt[k] = den[k]; if (den[k] > 3) Z[k] = num[k] / den[k]; }
  return { Z, Wt };
}

// ---- is the pattern more than chance? Shuffle the heading lists among the documents (positions stay) -----------------
// Each shuffle recomputes every document's value and the smoothed map; a cell is "beyond chance" when its observed value
// lies further from the shuffled mean than the largest deviation found anywhere on the map in 95% of the shuffles.
export function makeNull(P, R, kerns, mask) {
  const ids = [];
  P.books.forEach((b, i) => { if (R.active[i]) ids.push(i); });
  const cnt = new Int32Array(P.books.length);
  const valid = [];
  for (let i = 0; i < P.books.length; i++) if (!Number.isNaN(R.val[i])) { valid.push(i); let c = 0; for (const j of P.near[i]) if (R.active[j]) c++; cnt[i] = c; }
  const cells = [];
  for (let k = 0; k < NX * NY; k++) if (mask[k] && kerns.every((q) => q.den[k] > 3)) cells.push(k);
  return { ids, valid, cnt, kerns, cells, rows: kerns.map(() => []), done: 0, P, R };
}

function shuffleOnce(N, rnd) {
  const { P, R, ids, valid, cnt, kerns, cells } = N;
  const perm = ids.slice();
  for (let i = perm.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); const t = perm[i]; perm[i] = perm[j]; perm[j] = t; }
  const vec = new Array(P.books.length).fill(null);
  ids.forEach((id, k) => { vec[id] = R.vec[perm[k]]; });
  const val = new Float32Array(P.books.length).fill(NaN);
  for (const i of valid) {
    let s = 0;
    for (const j of P.near[i]) if (R.active[j]) s += dot(vec[i], vec[j]);
    val[i] = (s / cnt[i] - R.mu) * 100;
  }
  kerns.forEach((kern, q) => {
    const num = applyKern(kern, val), row = new Float32Array(cells.length);
    for (let c = 0; c < cells.length; c++) row[c] = num[cells[c]] / kern.den[cells[c]];
    N.rows[q].push(row);
  });
  N.done++;
}
export function runShuffles(N, k) { const rnd = Math.random; for (let i = 0; i < k; i++) shuffleOnce(N, rnd); }

// result per radius: z-scores of the observed map and the threshold
export function finishNull(N) {
  return N.kerns.map((kern, q) => {
    const rows = N.rows[q], m = rows.length, C = N.cells.length;
    const mean = new Float64Array(C), sd = new Float64Array(C);
    for (const r of rows) for (let c = 0; c < C; c++) mean[c] += r[c] / m;
    for (const r of rows) for (let c = 0; c < C; c++) { const d = r[c] - mean[c]; sd[c] += (d * d) / (m - 1); }
    for (let c = 0; c < C; c++) sd[c] = Math.max(Math.sqrt(sd[c]), 0.05);
    const maxAbs = rows.map((r) => { let mx = 0; for (let c = 0; c < C; c++) mx = Math.max(mx, Math.abs((r[c] - mean[c]) / sd[c])); return mx; }).sort((a, b) => a - b);
    const T = maxAbs[Math.min(m - 1, Math.ceil(0.95 * m) - 1)];
    const num = applyKern(kern, N.R.val);
    const status = new Int8Array(NX * NY); // +1 more alike than chance, -1 less alike, 0 not beyond chance, 2 not tested
    status.fill(2);
    let hot = 0, cold = 0;
    N.cells.forEach((k, c) => {
      const z = (num[k] / kern.den[k] - mean[c]) / sd[c];
      status[k] = z > T ? 1 : z < -T ? -1 : 0;
      if (status[k] === 1) hot++; else if (status[k] === -1) cold++;
    });
    return { bw: kern.bw, T, status, hot, cold, total: C, shuffles: m };
  });
}

// which cells lie inside the outline (ring of [lat, lon])
export function insideMask(ring) {
  const mask = new Uint8Array(NX * NY);
  const pts = ring.map((p) => [projX(p[1]), projY(p[0])]);
  for (let gy = 0; gy < NY; gy++) {
    const y = (gy + 0.5) * CELL;
    for (let gx = 0; gx < NX; gx++) {
      const x = (gx + 0.5) * CELL;
      let inside = false;
      for (let a = 0, b = pts.length - 1; a < pts.length; b = a++) {
        const [xa, ya] = pts[a], [xb, yb] = pts[b];
        if ((ya > y) !== (yb > y) && x < ((xb - xa) * (y - ya)) / (yb - ya) + xa) inside = !inside;
      }
      if (inside) mask[gy * NX + gx] = 1;
    }
  }
  return mask;
}

// ---- which headings make a spot red or blue? exact split of the smoothed value at a point into headings ----------------
export function drivers(P, R, mx, my, bw) {
  if (!R._tb) { // baseline per term: mean over all pairs of x_it * x_jt
    const S = new Map(), Q = new Map();
    for (let i = 0; i < P.books.length; i++) if (R.active[i]) { const v = R.vec[i]; for (const t of v.t) { S.set(t, (S.get(t) || 0) + v.w); Q.set(t, (Q.get(t) || 0) + v.w * v.w); } }
    const base = new Map();
    S.forEach((s, t) => base.set(t, (s * s - Q.get(t)) / (R.n * (R.n - 1))));
    R._tb = base;
  }
  let sumW = 0, nb = 0;
  const acc = new Map();
  for (let i = 0; i < P.books.length; i++) {
    if (Number.isNaN(R.val[i])) continue;
    const bx = P.books[i].x - LON0 * K, by = (LAT1 - P.books[i].lat) * 111;
    const d2 = (bx - mx) * (bx - mx) + (by - my) * (by - my);
    if (d2 > 9 * bw * bw) continue;
    const w = Math.exp(-d2 / (2 * bw * bw));
    if (w < 1e-4) continue;
    sumW += w; nb++;
    const v = R.vec[i];
    let c = 0;
    const part = new Map();
    for (const j of P.near[i]) {
      if (!R.active[j]) continue;
      c++;
      const u = R.vec[j];
      for (const t of v.t) if (u.t.includes(t)) part.set(t, (part.get(t) || 0) + v.w * u.w);
    }
    part.forEach((s, t) => acc.set(t, (acc.get(t) || 0) + (w * s) / c));
  }
  if (sumW < 1e-6) return null;
  const out = [];
  let total = 0;
  R._tb.forEach((b, t) => { const reg = (acc.get(t) || 0) / sumW; const score = (reg - b) * 100; total += score; out.push({ t, score }); });
  out.sort((a, b) => b.score - a.score);
  return { top: out.slice(0, 8).filter((o) => o.score > 0.02), low: out.slice(-3).filter((o) => o.score < -0.2).reverse(), total, weight: sumW, books: nb };
}

// Colour: RdBu reversed, centred on 0 (blue -6 ... white 0 ... red +8), like the figure in the paper.
const RDBU = ['#053061', '#2166ac', '#4393c3', '#92c5de', '#d1e5f0', '#f7f7f7', '#fddbc7', '#f4a582', '#d6604d', '#b2182b', '#67001f'];
const RGB = RDBU.map((h) => [1, 3, 5].map((k) => parseInt(h.slice(k, k + 2), 16)));
export function colourOf(v, lo = 6, hi = 8) {
  const t = v < 0 ? 0.5 * (1 + Math.max(v, -lo) / lo) : 0.5 + 0.5 * Math.min(v, hi) / hi;
  const f = t * 10, a = Math.min(9, Math.floor(f)), u = f - a;
  return [0, 1, 2].map((c) => Math.round(RGB[a][c] * (1 - u) + RGB[a + 1][c] * u));
}
export const LEGEND_STOPS = RDBU;
