import React, { useEffect, useMemo, useState } from 'react';
import './TestsLab.css';
import { loadFileOverrides, loadLocalOverrides, saveLocalOverrides, mergeOverrides } from './timeOverrides';

// Time editor: change the dates of books and gazetteer entries, tick "until now" for things that are still going on,
// then export manual_overrides.json and put it in public/data/ (replace the old one) so the change reaches everyone.
// Until it is exported, your edits are kept in this browser only (and shown on the Time search page in this browser).
const inp = { background: 'var(--bg-secondary, #1a1d23)', color: 'var(--text-primary, #e6e6e6)', border: '1px solid var(--border, #3a3f4b)', borderRadius: 4, padding: '3px 6px', font: 'inherit' };
const btn = { ...inp, cursor: 'pointer', padding: '5px 12px' };
const NUM = { ...inp, width: 78 };
const fmt = (v) => (v == null || v === '' ? '' : String(v));

export default function TimeEditor() {
  const [data, setData] = useState(null), [err, setErr] = useState(null);
  const [fileOv, setFileOv] = useState({ books: {}, gaz: {} });
  const [ov, setOv] = useState(() => loadLocalOverrides());
  const [tab, setTab] = useState('books');
  const [q, setQ] = useState('');
  const [rows, setRows] = useState({ books: [], gaz: [] });

  useEffect(() => {
    let off = false;
    Promise.all([
      fetch(`${process.env.PUBLIC_URL}/data/time_index.json`).then((r) => r.json()),
      loadFileOverrides(),
    ]).then(([d, f]) => {
      if (off) return;
      // keep the original index values so edits can be compared with them
      d.orig = { books: d.books.map((b) => [b[3], b[4], b[5]]), gaz: d.gaz.map((g) => [g[3], g[4]]) };
      const nowY = new Date().getFullYear();
      (d.open_gaz || []).forEach((i) => { d.gaz[i][4] = nowY; });
      (d.open_books || []).forEach((i) => { d.books[i][4] = nowY; });
      setFileOv(f); setData(d);
      const bk = new Set([...(d.open_books || []), ...d.books.map((b, i) => (b[5] === 6 ? i : -1)).filter((i) => i >= 0)]);
      const gz = new Set(d.open_gaz || []);
      const ids = new Map(d.books.map((b, i) => [b[0], i])), gids = new Map(d.gaz.map((g, i) => [g[0], i]));
      [...Object.keys(f.books), ...Object.keys(loadLocalOverrides().books)].forEach((id) => { if (ids.has(id)) bk.add(ids.get(id)); });
      [...Object.keys(f.gaz), ...Object.keys(loadLocalOverrides().gaz)].forEach((id) => { if (gids.has(id)) gz.add(gids.get(id)); });
      setRows({ books: [...bk], gaz: [...gz] });
    }).catch((e) => { console.error(e); if (!off) setErr(String(e)); });
    return () => { off = true; };
  }, []);

  const merged = useMemo(() => mergeOverrides(fileOv, ov), [fileOv, ov]);
  const setBook = (id, patch) => setOv((o) => { const n = { ...o, books: { ...o.books, [id]: { ...(o.books[id] || {}), ...patch } } }; saveLocalOverrides(n); return n; });
  const setGaz = (id, patch) => setOv((o) => { const n = { ...o, gaz: { ...o.gaz, [id]: { ...(o.gaz[id] || {}), ...patch } } }; saveLocalOverrides(n); return n; });
  const clearOne = (kind, id) => setOv((o) => { const n = { ...o, [kind]: { ...o[kind] } }; delete n[kind][id]; saveLocalOverrides(n); return n; });
  const reset = () => { if (window.confirm('Forget the edits made in this browser? The saved file stays.')) { const n = { books: {}, gaz: {} }; saveLocalOverrides(n); setOv(n); } };

  const exportFile = () => {
    const out = { note: 'Time index corrections. Put this file in public/data/manual_overrides.json. open = until now (end year = current year).', books: merged.books, gaz: merged.gaz };
    const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([JSON.stringify(out, null, 1)], { type: 'application/json' })); a.download = 'manual_overrides.json'; a.click();
  };

  const hits = useMemo(() => {
    if (!data || q.trim().length < 2) return [];
    const t = q.trim().toLowerCase(); const out = [];
    if (tab === 'books') { for (let i = 0; i < data.books.length && out.length < 15; i++) { const b = data.books[i]; if (b[0].toLowerCase() === t || b[1].toLowerCase().includes(t)) out.push(i); } }
    else { for (let i = 0; i < data.gaz.length && out.length < 15; i++) { const g = data.gaz[i]; if (g[0].toLowerCase() === t || g[2].toLowerCase().includes(t)) out.push(i); } }
    return out;
  }, [data, q, tab]);

  if (err) return <div style={{ padding: 24 }}>Could not load the index: {err}</div>;
  if (!data) return <div style={{ padding: 24 }}>Loading…</div>;
  const nowY = new Date().getFullYear();
  const list = rows[tab];
  const addRow = (i) => setRows((r) => (r[tab].includes(i) ? r : { ...r, [tab]: [i, ...r[tab]] }));
  const nEdits = Object.keys(ov.books).length + Object.keys(ov.gaz).length;

  const bookRow = (i) => {
    const b = data.books[i], id = b[0], o = merged.books[id] || {};
    const d0 = o.d0 ?? b[3], open = o.open ?? (data.open_books || []).includes(i), d1 = open ? nowY : (o.d1 ?? b[4]);
    const split = Array.isArray(o.ranges) && o.ranges.length > 0;
    const edited = !!ov.books[id];
    return (
      <tr key={id} style={{ borderTop: '1px solid var(--border, #3a3f4b)', background: edited ? 'rgba(111,177,255,.08)' : 'none' }}>
        <td style={{ padding: '6px 8px', whiteSpace: 'nowrap' }}>{id}</td>
        <td style={{ padding: '6px 8px', maxWidth: 420 }}>{b[1]}{b[2] ? <span className="tl-muted"> · published {b[2]}</span> : null}</td>
        {split ? <>
          <td colSpan={2} style={{ padding: '6px 8px' }}>
            {o.ranges.map((range, ri) => <div key={ri} style={{ display: 'flex', alignItems: 'center', gap: 5, marginBottom: 4 }}>
              <span className="tl-muted">Period {ri + 1}</span>
              <input aria-label={`Period ${ri + 1} start year`} style={NUM} value={fmt(range.d0 ?? range.start)} onChange={(e) => setBook(id, { ranges: o.ranges.map((r, j) => j === ri ? { ...r, d0: e.target.value, d1: r.d1 ?? r.end } : r) })} />
              <span>–</span>
              <input aria-label={`Period ${ri + 1} end year`} style={NUM} value={fmt(range.d1 ?? range.end)} onChange={(e) => setBook(id, { ranges: o.ranges.map((r, j) => j === ri ? { ...r, d1: e.target.value, d0: r.d0 ?? r.start } : r) })} />
              <button style={{ ...btn, padding: '2px 7px' }} title="Remove this period" disabled={o.ranges.length < 2} onClick={() => setBook(id, { ranges: o.ranges.filter((_, j) => j !== ri) })}>×</button>
            </div>)}
            <button style={{ ...btn, padding: '2px 7px' }} onClick={() => setBook(id, { ranges: [...o.ranges, { d0: '', d1: '' }] })}>+ Add separate period</button>
          </td>
          <td className="tl-muted">Separate periods</td>
        </> : <>
          <td><input style={NUM} value={fmt(d0)} onChange={(e) => setBook(id, { d0: e.target.value, open })} /></td>
          <td><input style={NUM} value={fmt(d1)} disabled={open} onChange={(e) => setBook(id, { d1: e.target.value, d0, open })} /></td>
          <td style={{ textAlign: 'center' }}><input type="checkbox" checked={!!open} onChange={(e) => setBook(id, { open: e.target.checked, d0, d1: e.target.checked ? '' : fmt(d1) })} /> <button style={{ ...btn, padding: '2px 7px' }} title="Represent separate periods" onClick={() => setBook(id, { ranges: [{ d0: fmt(d0), d1: fmt(d1) }] })}>Split periods</button></td>
        </>}
        <td><input style={{ ...inp, width: 220 }} placeholder="note" value={o.note || ''} onChange={(e) => setBook(id, { note: e.target.value })} /></td>
        <td>{edited ? <button style={btn} onClick={() => clearOne('books', id)}>undo</button> : null}</td>
      </tr>
    );
  };
  const gazRow = (i) => {
    const g = data.gaz[i], id = g[0], o = merged.gaz[id] || {};
    const open = o.open ?? (data.open_gaz || []).includes(i);
    const s = o.start ?? g[3], e = open ? nowY : (o.end ?? g[4]);
    const edited = !!ov.gaz[id];
    return (
      <tr key={id} style={{ borderTop: '1px solid var(--border, #3a3f4b)', background: edited ? 'rgba(111,177,255,.08)' : 'none' }}>
        <td style={{ padding: '6px 8px', whiteSpace: 'nowrap' }}>{id} · {g[1]}</td>
        <td style={{ padding: '6px 8px', maxWidth: 420 }}>{g[2]}<span className="tl-muted"> · {g[6]} books</span></td>
        <td><input style={NUM} value={fmt(s)} onChange={(ev) => setGaz(id, { start: ev.target.value, open })} /></td>
        <td><input style={NUM} value={fmt(e)} disabled={open} onChange={(ev) => setGaz(id, { end: ev.target.value, start: s, open })} /></td>
        <td style={{ textAlign: 'center' }}><input type="checkbox" checked={!!open} onChange={(ev) => setGaz(id, { open: ev.target.checked, start: s, end: ev.target.checked ? '' : fmt(e) })} /></td>
        <td />
        <td>{edited ? <button style={btn} onClick={() => clearOne('gaz', id)}>undo</button> : null}</td>
      </tr>
    );
  };

  return (
    <div style={{ padding: '16px 20px', maxWidth: 1250, margin: '0 auto' }}>
      <h2 style={{ margin: '0 0 4px' }}>Time editor</h2>
      <p className="tl-muted" style={{ margin: '0 0 12px' }}>
        Change the start and end year of a book or a gazetteer entry, split a book into separate periods, or tick “until now” so its end year is always the current year ({nowY}).
        The list shows manual dates and “until now” items; search to add any other book (by title or LCCN) or gazetteer entry.
        Years before the common era are negative (-450). Your edits show on the Time search page in this browser straight away;
        to make them permanent for everyone, export the file and put it in <code>public/data/manual_overrides.json</code>.
      </p>
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center', marginBottom: 10 }}>
        <button style={{ ...btn, fontWeight: tab === 'books' ? 700 : 400 }} onClick={() => setTab('books')}>Books ({rows.books.length})</button>
        <button style={{ ...btn, fontWeight: tab === 'gaz' ? 700 : 400 }} onClick={() => setTab('gaz')}>Gazetteer entries ({rows.gaz.length})</button>
        <input style={{ ...inp, minWidth: 260 }} placeholder={tab === 'books' ? 'search a title or LCCN to add' : 'search a gazetteer entry to add'} value={q} onChange={(e) => setQ(e.target.value)} />
        <span style={{ flex: 1 }} />
        <span className="tl-muted">{nEdits} edit{nEdits === 1 ? '' : 's'} in this browser</span>
        <button style={btn} onClick={exportFile}>Export manual_overrides.json</button>
        <button style={btn} onClick={reset}>Forget my edits</button>
      </div>
      {hits.length > 0 && (
        <div style={{ border: '1px solid var(--border, #3a3f4b)', borderRadius: 6, padding: 8, marginBottom: 12 }}>
          {hits.map((i) => (
            <div key={i} style={{ padding: '3px 0', cursor: 'pointer' }} onClick={() => { addRow(i); setQ(''); }}>
              + {tab === 'books' ? `${data.books[i][0]} — ${data.books[i][1]}` : `${data.gaz[i][0]} — ${data.gaz[i][2]}`}
            </div>
          ))}
        </div>
      )}
      <table style={{ borderCollapse: 'collapse', width: '100%', fontSize: 13 }}>
        <thead><tr className="tl-muted" style={{ textAlign: 'left' }}><th style={{ padding: '4px 8px' }}>{tab === 'books' ? 'LCCN' : 'Entry'}</th><th style={{ padding: '4px 8px' }}>{tab === 'books' ? 'Title' : 'Label'}</th><th>From</th><th>To</th><th>Until now</th><th>{tab === 'books' ? 'Note' : ''}</th><th /></tr></thead>
        <tbody>{list.map((i) => (tab === 'books' ? bookRow(i) : gazRow(i)))}</tbody>
      </table>
      {list.length === 0 && <p className="tl-muted">Nothing here yet. Search above to add an item.</p>}
    </div>
  );
}
