Object.keys(UK_MAPS).forEach((k) => { if (!(k in UK)) UK[k] = UK_MAPS[k]; });

const ROMAN = ['', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI', 'XII', 'XIII', 'XIV', 'XV', 'XVI', 'XVII', 'XVIII', 'XIX', 'XX', 'XXI'];

// plural forms for counted nouns: [one, few, many]
const PL = {
  records: ['запис', 'записи', 'записів'], events: ['подія', 'події', 'подій'], people: ['особа', 'особи', 'осіб'],
  books: ['книжка', 'книжки', 'книжок'], cells: ['комірка', 'комірки', 'комірок'], states: ['держава', 'держави', 'держав'],
};
export function plUk(kind, n) {
  const f = PL[kind] || [kind, kind, kind], a = Math.abs(Math.round(n)), m10 = a % 10, m100 = a % 100;
  if (m10 === 1 && m100 !== 11) return f[0];
  if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return f[1];
  return f[2];
}

const SUMMARY_NONE = '(no state in the gazetteer)';
function sumUk(s) {
  return s.split(' → ').map((part) => {
    const m = part.match(/^([^:]+): (.*)$/);
    if (!m) return part;
    const names = m[2].split(' / ').map((x) => {
      const q = x.match(/^(.*?) (\d+%)$/);
      const nm = q ? q[1] : x;
      const t = nm === SUMMARY_NONE ? '(немає держави в реєстрі)' : tUk(nm);
      return q ? `${t} ${q[2]}` : t;
    });
    return `${m[1]}: ${names.join(' / ')}`;
  }).join(' → ');
}

// Translate a data string: whole phrase first, then its parts (lists, parentheses, summaries).
export function tUk(s) {
  if (s == null || typeof s !== 'string' || s === '') return s;
  if (UK[s]) return UK[s];
  let m = s.match(/^several \((\d+)\): see the Timeline$/);
  if (m) return `кілька (${m[1]}): див. хронологію`;
  if (/ → /.test(s) || /^[-\d.]+: .*\d+%/.test(s)) return sumUk(s);
  if (s.indexOf(' / ') > 0) return s.split(' / ').map(tUk).join(' / ');
  m = s.match(/^(.*?)\s*\((.*)\)\s*$/);
  if (m && m[1]) { const h = tUk(m[1]), p = tUk(m[2]); if (h !== m[1] || p !== m[2]) return `${h} (${p})`; }
  if (s.indexOf(', ') > 0) { const parts = s.split(', '), t = parts.map(tUk); if (t.some((x, i) => x !== parts[i])) return t.join(', '); }
  return s;
}

// Frame labels such as "c. 5050–2950 BCE", "9th century", "to 1054".
export function labUk(s) {
  if (!s) return s;
  return String(s)
    .replace(/(\d+)(?:st|nd|rd|th)–(\d+)(?:st|nd|rd|th) c\./, (x, a, b) => `${ROMAN[+a]}–${ROMAN[+b]} ст.`)
    .replace(/(\d+)(?:st|nd|rd|th) century/, (x, a) => `${ROMAN[+a]} століття`)
    .replace(/^c\. /, 'бл. ').replace(/ BCE/g, ' до н. е.').replace(/ CE/g, ' н. е.').replace(/^to /, 'до ');
}
