import React, { useEffect, useMemo, useRef, useState } from 'react';
import { spread, azFwd, azInv } from './testsLabLogic';

const rngOf = (seed) => { let a = 0; for (let i = 0; i < seed.length; i++) a = (Math.imul(a, 31) + seed.charCodeAt(i)) | 0; return () => { a = (a + 0x6d2b79f5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; };
const bearingOf = (th) => (((90 - th) % 180) + 180) % 180;

// One zoomable map for ovals (standard deviational ellipses), used by the tests lab and the drift lab.
// Basemap: public/data/world_outline.json (Natural Earth, countries from the Atlantic to Central Asia, Turkey included).
// Projection: plain longitude/latitude, with longitude shrunk by cos(48.5°) so that Ukraine looks right. One unit = 0.01° of latitude.

const K = Math.cos((48.5 * Math.PI) / 180);
const U = 100;
const X = (lon) => lon * K * U;
const Y = (lat) => -lat * U;
const KM_U = U / 110.57; // map units per km
const KYIV = [50.45, 30.52];
const RAD = Math.PI / 180;

const bearingTo = (la1, lo1, la2, lo2) => {
  const y = Math.sin((lo2 - lo1) * RAD) * Math.cos(la2 * RAD);
  const x = Math.cos(la1 * RAD) * Math.sin(la2 * RAD) - Math.sin(la1 * RAD) * Math.cos(la2 * RAD) * Math.cos((lo2 - lo1) * RAD);
  return ((Math.atan2(y, x) / RAD) + 360) % 360;
};
export const axisOff = (a, b) => { const d = Math.abs(a - b) % 180; return Math.min(d, 180 - d); };
const compass = (b) => ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'][Math.round(((b % 360) / 45)) % 8];

// a point in km east and north of the oval's centre
const local = (o, la, lo) => { if (o.az) { const q = azFwd(o.lat, o.lon, la, lo); return { e: q[0], n: q[1] }; } return { e: (lo - o.lon) * 111.32 * Math.cos(o.lat * RAD), n: (la - o.lat) * 110.57 }; };
const unlocal = (o, e, n) => (o.az ? azInv(o.lat, o.lon, e, n) : [o.lat + n / 110.57, o.lon + e / (111.32 * Math.cos(o.lat * RAD))]);
// the outline of an oval (and its long axis) as points on the map; on the azimuthal plane these are curves
const ovalOutline = (o, steps = 96) => { const t = o.bearing * RAD, out = []; for (let i = 0; i <= steps; i++) { const f = (i / steps) * 2 * Math.PI, u = o.ra * Math.cos(f), v = o.rb * Math.sin(f); out.push(unlocal(o, u * Math.sin(t) + v * Math.cos(t), u * Math.cos(t) - v * Math.sin(t))); } return out; };
const axisLine = (o, steps = 48) => { const t = o.bearing * RAD, out = []; for (let i = 0; i <= steps; i++) { const u = o.ra * (-1 + (2 * i) / steps); out.push(unlocal(o, u * Math.sin(t), u * Math.cos(t))); } return out; };
// long-axis unit vector (east, north) from the bearing, measured clockwise from north
const inOval = (o, la, lo) => {
  const { e, n } = local(o, la, lo), t = o.bearing * RAD;
  const u = e * Math.sin(t) + n * Math.cos(t), v = -e * Math.cos(t) + n * Math.sin(t);
  return (u / o.ra) ** 2 + (v / o.rb) ** 2 <= 1;
};
const inRings = (rings, la, lo) => {
  let c = false;
  for (const r of rings) for (let i = 0, j = r.length - 1; i < r.length; j = i++) {
    const [yi, xi] = r[i], [yj, xj] = r[j];
    if ((yi > la) !== (yj > la) && lo < ((xj - xi) * (la - yi)) / (yj - yi) + xi) c = !c;
  }
  return c;
};

// How much of the oval is Ukraine, how much of Ukraine is in the oval, and how many of the heading's own places and books lie inside it.
export function coverage(o, ukraine, pool, poolVar) {
  const out = {};
  out.alongAxis = (o.ra * o.ra) / (o.ra * o.ra + o.rb * o.rb);
  if (poolVar) out.varShare = (o.ra * o.ra + o.rb * o.rb) / poolVar;
  const pts = o.pts || [];
  out.placesN = pts.length; out.placesIn = pts.filter((p) => inOval(o, p[0], p[1])).length;
  out.booksN = pts.reduce((s, p) => s + p[2], 0); out.booksIn = pts.filter((p) => inOval(o, p[0], p[1])).reduce((s, p) => s + p[2], 0);
  if (ukraine && ukraine.length) {
    let ovalN = 0, ovalUa = 0, uaN = 0, uaIn = 0;
    const reach = Math.max(o.ra, o.rb) * 1.05, G = 70;
    for (let i = 0; i < G; i++) for (let j = 0; j < G; j++) {
      const e = (-1 + (2 * (i + 0.5)) / G) * reach, n = (-1 + (2 * (j + 0.5)) / G) * reach, t = o.bearing * RAD;
      const u = e * Math.sin(t) + n * Math.cos(t), v = -e * Math.cos(t) + n * Math.sin(t);
      if ((u / o.ra) ** 2 + (v / o.rb) ** 2 > 1) continue;
      ovalN++;
      { const ll = unlocal(o, e, n); if (inRings(ukraine, ll[0], ll[1])) ovalUa++; }
    }
    for (let i = 0; i < 80; i++) for (let j = 0; j < 55; j++) {
      const lo = 22 + (18.6 * (i + 0.5)) / 80, la = 44.2 + (8.4 * (j + 0.5)) / 55;
      if (!inRings(ukraine, la, lo)) continue;
      uaN++; if (inOval(o, la, lo)) uaIn++;
    }
    out.ovalInUkraine = ovalN ? ovalUa / ovalN : 0; out.ukraineInOval = uaN ? uaIn / uaN : 0;
  }
  if (pool && pool.length) {
    let tot = 0, inn = 0;
    for (const p of pool) { const w = p[2] || 1; tot += w; if (inOval(o, p[0], p[1])) inn += w; }
    out.poolShare = tot ? inn / tot : 0;
  }
  return out;
}

const pctS = (x) => `${Math.round(x * 100)}%`;
const LABELS = ['Ukraine', 'Russia', 'Turkey', 'Poland', 'Germany', 'Romania', 'Belarus', 'Hungary', 'Austria', 'Moldova', 'Lithuania', 'Kazakhstan', 'Georgia', 'Bulgaria', 'France', 'Italy', 'Sweden', 'Finland', 'Greece', 'Serbia', 'Czechia', 'Latvia', 'Estonia', 'Azerbaijan', 'Armenia', 'Norway', 'Spain', 'United Kingdom'];
const NAME_OVERRIDE = { Ukraine: [49.0, 31.4], Russia: [56.5, 45], Turkey: [39.2, 33.5], Norway: [62, 9], Finland: [63.5, 26], Sweden: [62, 16], France: [46.6, 2.5], Italy: [42.8, 12.6], Spain: [40.2, -3.5], 'United Kingdom': [53, -1.8], Kazakhstan: [48, 66] };

let EUROPE = null;
const useEurope = () => {
  const [d, setD] = useState(EUROPE);
  useEffect(() => {
    if (EUROPE) return undefined;
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/world_outline.json`).then((r) => r.json()).then((x) => { EUROPE = x; if (!off) setD(x); }).catch(() => {});
    return () => { off = true; };
  }, []);
  return d;
};

const ring = (r) => 'M' + r.map(([la, lo]) => `${X(lo).toFixed(0)},${Y(la).toFixed(0)}`).join('L') + 'Z';
const VIEWS = {
  ukraine: { lon: [21.2, 41.4], lat: [43.6, 53.2] },
  europe: { lon: [-24, 72], lat: [27, 67] },
  world: { lon: [-180, 180], lat: [-58, 82] },
};
const ASPECT = 0.62;
const fitBox = (x0, x1, y0, y1) => {
  let w = x1 - x0, h = y1 - y0;
  if (h / w > ASPECT) w = h / ASPECT;
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
  return { cx, cy, w };
};
const viewOf = (name) => { const v = VIEWS[name]; return fitBox(X(v.lon[0]), X(v.lon[1]), Y(v.lat[1]), Y(v.lat[0])); };

/**
 * ovals: [{ id, label, lat, lon, ra, rb (km), bearing (long axis, ° clockwise from north), color, solid, pts: [[lat, lon, books, name?]] , facts: [string] }]
 * cities: [{ name, lat, lon, color }] (the directions the long axes are compared with)
 * ukraine: rings [[lat, lon]], pool: optional [[lat, lon, weight]] of all places (for "share of all places")
 */
export default function OvalMap({ ovals: ovalsIn, sel, setSel, cities = [], ukraine, pool, onHover, extra, startView = 'europe', unit = 'books', legend, fitCities = false }) {
  const eu = useEurope();
  const [scale, setScale] = useState(1);
  const ovals = useMemo(() => ovalsIn.map((o) => (scale === 1 ? o : { ...o, ra: o.ra * scale, rb: o.rb * scale })), [ovalsIn, scale]);
  const [view, setView] = useState(() => viewOf(startView));
  const svgRef = useRef(null);
  const drag = useRef(null);
  const [wpx, setWpx] = useState(900);
  const h = view.w * ASPECT;
  const s = view.w / wpx; // map units per screen pixel

  useEffect(() => {
    const el = svgRef.current; if (!el) return undefined;
    const wheel = (e) => {
      e.preventDefault();
      const r = el.getBoundingClientRect(), f = e.deltaY < 0 ? 0.8 : 1.25;
      setView((v) => {
        const w = Math.min(26000, Math.max(250, v.w * f)), fx = (e.clientX - r.left) / r.width, fy = (e.clientY - r.top) / r.height;
        const ax = v.cx - v.w / 2 + fx * v.w, ay = v.cy - (v.w * ASPECT) / 2 + fy * v.w * ASPECT;
        return { w, cx: ax + (0.5 - fx) * w, cy: ay + (0.5 - fy) * w * ASPECT };
      });
    };
    el.addEventListener('wheel', wheel, { passive: false });
    const ro = new ResizeObserver(() => setWpx(el.getBoundingClientRect().width || 900));
    ro.observe(el);
    return () => { el.removeEventListener('wheel', wheel); ro.disconnect(); };
  }, []);

  const zoom = (f) => setView((v) => ({ ...v, w: Math.min(26000, Math.max(250, v.w * f)) }));
  const ukBox = useMemo(() => {
    const all = (ukraine || []).flat();
    if (!all.length) return [X(22), X(40.5), Y(52.5), Y(44)];
    const la = all.map((p) => p[0]), lo = all.map((p) => p[1]);
    return [X(Math.min(...lo)), X(Math.max(...lo)), Y(Math.max(...la)), Y(Math.min(...la))];
  }, [ukraine]);
  const cur = ovals.find((o) => o.id === sel) || null;
  const hv = view.w * ASPECT;
  const far = cur ? (cur.pts || []).filter((p) => X(p[1]) < view.cx - view.w / 2 || X(p[1]) > view.cx + view.w / 2 || Y(p[0]) < view.cy - hv / 2 || Y(p[0]) > view.cy + hv / 2) : [];
  const fitDots = () => {
    if (!cur) return;
    const cx_ = fitCities ? cities.map((c) => X(c.lon)) : [], cy_ = fitCities ? cities.map((c) => Y(c.lat)) : [];
    const xs = [X(cur.lon), ...(cur.pts || []).map((p) => X(p[1])), ukBox[0], ukBox[1], ...cx_], ys = [Y(cur.lat), ...(cur.pts || []).map((p) => Y(p[0])), ukBox[2], ukBox[3], ...cy_];
    const x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys), px = (x1 - x0) * 0.08 + 200, py = (y1 - y0) * 0.08 + 200;
    setView(fitBox(x0 - px, x1 + px, y0 - py, y1 + py));
  };
  const poolVar = useMemo(() => {
    if (!pool || pool.length < 5) return null;
    const sp = spread(pool.map((p) => p[0]), pool.map((p) => p[1]), pool.map((p) => p[2] || 1), !!(cur && cur.az));
    return sp ? sp.ra * sp.ra + sp.rb * sp.rb : null;
  }, [pool, cur && cur.az]); // eslint-disable-line
  const cov = useMemo(() => (cur ? coverage(cur, ukraine, pool, poolVar) : null), [cur, ukraine, pool, poolVar]);

  // the same oval, drawn from random places: sets of the same number of places from all places in the collection
  const chance = useMemo(() => {
    if (!cur || !pool || pool.length < 20) return null;
    const k = (cur.pts || []).length; if (k < 3) return null;
    const o = ovalsIn.find((q) => q.id === cur.id) || cur, rnd = rngOf(String(cur.id)), N = 600;
    const rad = (ra, rb) => Math.sqrt(ra * rb);
    const own = { rad: rad(o.ra, o.rb), el: o.ra / o.rb };
    const sizes = [], els = [], lean = Object.fromEntries(cities.map((c) => [c.name, 0])); let n = 0;
    const idx = (len, m) => { const a = Array.from({ length: len }, (_, i) => i); for (let i = 0; i < m; i++) { const j = i + Math.floor(rnd() * (len - i)); [a[i], a[j]] = [a[j], a[i]]; } return a.slice(0, m); };
    for (let t = 0; t < N; t++) {
      const q = idx(pool.length, Math.min(k, pool.length)).map((i) => pool[i]);
      const sp = spread(q.map((p) => p[0]), q.map((p) => p[1]), q.map((p) => p[2] || 1), cur.az ? true : cur.autoAz ? 'auto' : false); if (!sp) continue;
      n++; sizes.push(rad(sp.ra, sp.rb)); els.push(sp.elong);
      if (sp.elong >= 1.5) { const b = bearingOf(sp.theta); cities.forEach((c) => { if (axisOff(b, bearingTo(sp.latC, sp.lonC, c.lat, c.lon)) <= 22.5) lean[c.name] += 1; }); }
    }
    // the heading's own places, resampled: how stable is the direction of its long axis?
    const pts = cur.pts, bs = [];
    for (let t = 0; t < 600; t++) {
      const q = Array.from({ length: pts.length }, () => pts[Math.floor(rnd() * pts.length)]);
      const sp = spread(q.map((p) => p[0]), q.map((p) => p[1]), q.map((p) => p[2] || 1), cur.az ? true : cur.autoAz ? 'auto' : false); if (sp) bs.push(bearingOf(sp.theta));
    }
    bs.sort((a, b) => a - b);
    const med = (a) => { const b = a.slice().sort((x, y) => x - y); return b[Math.floor(b.length / 2)]; };
    return {
      k, n, own, sizeMed: med(sizes), elMed: med(els), shareEl: els.filter((e) => e >= 1.5).length / n,
      smaller: sizes.filter((x) => x <= own.rad).length / n, moreEl: els.filter((e) => e <= own.el).length / n,
      lean: Object.fromEntries(cities.map((c) => [c.name, lean[c.name] / n])),
      bLo: bs.length ? bs[Math.floor(bs.length * 0.1)] : null, bHi: bs.length ? bs[Math.floor(bs.length * 0.9)] : null,
    };
  }, [cur && cur.id, pool, ovalsIn, cities.map((c) => c.name).join()]); // eslint-disable-line

  // when an oval is selected, fit the whole oval and Ukraine in view
  useEffect(() => {
    if (!cur) return;
    const t = cur.bearing * RAD, cx = X(cur.lon), cy = Y(cur.lat);
    const ra = cur.ra * KM_U, rb = cur.rb * KM_U;
    const hx = Math.sqrt((ra * Math.sin(t)) ** 2 + (rb * Math.cos(t)) ** 2), hy = Math.sqrt((ra * Math.cos(t)) ** 2 + (rb * Math.sin(t)) ** 2);
    let ox0 = cx - hx, ox1 = cx + hx, oy0 = cy - hy, oy1 = cy + hy;
    if (cur.az) { const ol = ovalOutline(cur), oxs = ol.map((q) => X(q[1])), oys = ol.map((q) => Y(q[0])); ox0 = Math.min(...oxs); ox1 = Math.max(...oxs); oy0 = Math.min(...oys); oy1 = Math.max(...oys); }
    const x0 = Math.min(ox0, ukBox[0]), x1 = Math.max(ox1, ukBox[1]), y0 = Math.min(oy0, ukBox[2]), y1 = Math.max(oy1, ukBox[3]);
    const padX = (x1 - x0) * 0.08, padY = (y1 - y0) * 0.08;
    const base = fitBox(x0 - padX, x1 + padX, y0 - padY, y1 + padY);
    // include every dot when that does not mean zooming out to half the world
    const dx = [x0, x1, ...(cur.pts || []).map((p) => X(p[1])), ...(fitCities ? cities.map((c) => X(c.lon)) : [])], dy = [y0, y1, ...(cur.pts || []).map((p) => Y(p[0])), ...(fitCities ? cities.map((c) => Y(c.lat)) : [])];
    const ax0 = Math.min(...dx), ax1 = Math.max(...dx), ay0 = Math.min(...dy), ay1 = Math.max(...dy), qx = (ax1 - ax0) * 0.08 + 60, qy = (ay1 - ay0) * 0.08 + 60;
    const all = fitBox(ax0 - qx, ax1 + qx, ay0 - qy, ay1 + qy);
    if (all.w <= (fitCities ? 14000 : 5200)) { setView(all); return; }
    if (fitCities && cities.length) {
      const cx2 = cities.map((c) => X(c.lon)), cy2 = cities.map((c) => Y(c.lat));
      const bx0 = Math.min(x0, ...cx2), bx1 = Math.max(x1, ...cx2), by0 = Math.min(y0, ...cy2), by1 = Math.max(y1, ...cy2), bpx = (bx1 - bx0) * 0.08 + 60, bpy = (by1 - by0) * 0.08 + 60;
      setView(fitBox(bx0 - bpx, bx1 + bpx, by0 - bpy, by1 + bpy)); return;
    }
    setView(base);
  }, [sel]); // eslint-disable-line

  const down = (e) => { drag.current = { x: e.clientX, y: e.clientY, v: view, moved: false }; };
  const move = (e) => {
    const d = drag.current; if (!d) return;
    const r = svgRef.current.getBoundingClientRect(), dx = e.clientX - d.x, dy = e.clientY - d.y;
    if (Math.abs(dx) + Math.abs(dy) > 4) d.moved = true;
    if (d.moved) setView({ w: d.v.w, cx: d.v.cx - (dx / r.width) * d.v.w, cy: d.v.cy - (dy / r.height) * d.v.w * ASPECT });
  };
  const up = () => { setTimeout(() => { drag.current = null; }, 0); };
  const pick = (id) => { if (drag.current && drag.current.moved) return; setSel(sel === id ? null : id); };

  // graticule
  const step = view.w > 14000 ? 30 : view.w > 8000 ? 20 : view.w > 4000 ? 10 : view.w > 1800 ? 5 : 2;
  const grid = [];
  for (let lon = -180; lon <= 180; lon += step) grid.push(<line key={`x${lon}`} x1={X(lon)} x2={X(lon)} y1={Y(90)} y2={Y(-90)} stroke="#222a33" strokeWidth="1" vectorEffect="non-scaling-stroke" />);
  for (let lat = -80; lat <= 80; lat += step) grid.push(<line key={`y${lat}`} x1={X(-180)} x2={X(180)} y1={Y(lat)} y2={Y(lat)} stroke="#222a33" strokeWidth="1" vectorEffect="non-scaling-stroke" />);
  const gridLabels = [];
  for (let lon = -180; lon <= 180; lon += step) if (X(lon) > view.cx - view.w / 2 && X(lon) < view.cx + view.w / 2) gridLabels.push(<text key={`tx${lon}`} x={X(lon) + 3 * s} y={view.cy + h / 2 - 5 * s} fill="#6f7782" fontSize={10.5 * s}>{lon}°{lon < 0 ? 'W' : 'E'}</text>);
  for (let lat = -80; lat <= 80; lat += step) if (Y(lat) > view.cy - h / 2 && Y(lat) < view.cy + h / 2) gridLabels.push(<text key={`ty${lat}`} x={view.cx - view.w / 2 + 4 * s} y={Y(lat) - 3 * s} fill="#6f7782" fontSize={10.5 * s}>{Math.abs(lat)}°{lat < 0 ? 'S' : 'N'}</text>);

  const showAll = !cur;
  const drawn = ovals.filter((o) => showAll || o.id === sel);
  const kyivX = X(KYIV[1]), kyivY = Y(KYIV[0]);

  return (
    <div className="tl-ovalmap">
      <div className="tl-zoombtns" style={{ flexWrap: 'wrap' }}>
        <button type="button" onClick={() => zoom(0.7)} aria-label="Zoom in">+</button>
        <button type="button" onClick={() => zoom(1.4)} aria-label="Zoom out">−</button>
        <button type="button" onClick={() => setView(viewOf('ukraine'))}>Ukraine</button>
        <button type="button" onClick={() => setView(viewOf('europe'))}>Europe and Turkey</button>
        <button type="button" onClick={() => setView(viewOf('world'))}>World</button>
        {cur && <button type="button" onClick={() => setSel(null)}>Show all ovals</button>}
        {cur && far.length > 0 && <button type="button" onClick={fitDots}>Show all dots</button>}
        <label className="tl-muted" style={{ display: 'inline-flex', gap: 6, alignItems: 'center' }}>Oval size <select value={scale} onChange={(e) => setScale(+e.target.value)} style={{ background: '#171a20', color: '#f2f3f5', border: '1px solid #2c333b', borderRadius: 6, padding: '3px 6px' }}><option value={1}>1× (as in the paper)</option><option value={1.5}>1.5×</option><option value={2}>2×</option></select></label>
        <span className="tl-muted">scroll to zoom, drag to move, click an oval to inspect it</span>
      </div>
      <svg ref={svgRef} viewBox={`${view.cx - view.w / 2} ${view.cy - h / 2} ${view.w} ${h}`} className="tl-svg" role="img" aria-label="Map of the ovals"
        style={{ touchAction: 'none', cursor: drag.current && drag.current.moved ? 'grabbing' : 'grab', background: '#0d1117' }}
        onPointerDown={down} onPointerMove={move} onPointerUp={up} onPointerLeave={up}>
        {grid}
        {eu && eu.countries.map((c) => (
          <path key={c.n} d={c.r.map(ring).join('')} fill={c.n === 'Ukraine' ? '#243245' : '#161c24'} stroke={c.n === 'Ukraine' ? '#a7b8cc' : '#36414e'} strokeWidth={c.n === 'Ukraine' ? 1.8 : 1} vectorEffect="non-scaling-stroke" strokeLinejoin="round" />
        ))}
        {ukraine && <path d={ukraine.map(ring).join('')} fill="#243245" stroke="#a7b8cc" strokeWidth="1.8" vectorEffect="non-scaling-stroke" strokeLinejoin="round" />}
        {gridLabels}
        {eu && view.w < 7000 && LABELS.map((nm) => {
          const c = eu.countries.find((q) => q.n === nm); if (!c) return null;
          const pos = NAME_OVERRIDE[nm] || (() => { const big = c.r.slice().sort((a, b) => b.length - a.length)[0]; return [big.reduce((t, p) => t + p[0], 0) / big.length, big.reduce((t, p) => t + p[1], 0) / big.length]; })();
          const sz = nm === 'Ukraine' ? 13 : 10.5;
          return <text key={nm} x={X(pos[1])} y={Y(pos[0])} textAnchor="middle" fill={nm === 'Ukraine' ? '#dbe6f3' : '#59636f'} fontSize={sz * s} fontWeight={nm === 'Ukraine' ? 700 : 500} style={{ pointerEvents: 'none', letterSpacing: '0.04em' }}>{nm.toUpperCase()}</text>;
        })}

        {drawn.map((o) => {
          const cx = X(o.lon), cy = Y(o.lat), isSel = o.id === sel;
          return (
            <g key={o.id} onClick={() => pick(o.id)} onMouseEnter={onHover ? (e) => onHover(e, o) : undefined} onMouseMove={onHover ? (e) => onHover(e, o) : undefined} onMouseLeave={onHover ? () => onHover(null, o) : undefined} style={{ cursor: 'pointer' }}>
              {o.az ? (
                <path d={'M' + ovalOutline(o).map((q) => `${X(q[1]).toFixed(1)},${Y(q[0]).toFixed(1)}`).join('L') + 'Z'}
                  fill={o.color} fillOpacity={isSel ? 0.2 : o.solid ? 0.08 : 0.03} stroke={o.color} strokeWidth={isSel ? 2.6 : o.solid ? 1.5 : 0.9} strokeOpacity={isSel || o.solid ? 0.95 : 0.5} strokeDasharray={o.solid || isSel ? undefined : '4 4'} vectorEffect="non-scaling-stroke" />
              ) : (
              <ellipse cx={cx} cy={cy} rx={o.ra * KM_U} ry={o.rb * KM_U} transform={`rotate(${o.bearing - 90} ${cx} ${cy})`}
                fill={o.color} fillOpacity={isSel ? 0.2 : o.solid ? 0.08 : 0.03} stroke={o.color} strokeWidth={isSel ? 2.6 : o.solid ? 1.5 : 0.9} strokeOpacity={isSel || o.solid ? 0.95 : 0.5} strokeDasharray={o.solid || isSel ? undefined : '4 4'} vectorEffect="non-scaling-stroke" />
              )}
            </g>
          );
        })}

        {cities.map((c, i) => {
          const x = X(c.lon), y = Y(c.lat), b = Math.round(bearingTo(KYIV[0], KYIV[1], c.lat, c.lon));
          return (
            <g key={c.name} opacity={cur ? 0.9 : 0.8} style={{ pointerEvents: 'none' }}>
              <line x1={kyivX} y1={kyivY} x2={x} y2={y} stroke={c.color} strokeWidth="1.6" strokeDasharray="3 5" vectorEffect="non-scaling-stroke" />
              <circle cx={x} cy={y} r={3.2 * s} fill={c.color} />
              <text x={x + 8 * s} y={y + 4 * s} fill={c.color} fontSize={12.5 * s} fontWeight="600">{c.name} ({b}° from Kyiv)</text>
            </g>
          );
        })}
        <g style={{ pointerEvents: 'none' }}>
          <circle cx={kyivX} cy={kyivY} r={8 * s} fill="none" stroke="#fff" strokeWidth="1.4" strokeDasharray="2 2" vectorEffect="non-scaling-stroke" />
          <text x={kyivX + 7 * s} y={kyivY + 14 * s} fill="#fff" fontSize={11.5 * s} fontWeight="600">Kyiv</text>
        </g>

        {cur && (() => {
          const cx = X(cur.lon), cy = Y(cur.lat);
          let t = cur.bearing * RAD;
          const axPts = cur.az ? axisLine(cur) : null;
          if (axPts) { const m = (axPts.length - 1) / 2, a = axPts[m + 1], b0 = axPts[m]; t = Math.atan2(X(a[1]) - X(b0[1]), -(Y(a[0]) - Y(b0[0]))); if (t < 0) t += Math.PI; }
          const ra = cur.ra * KM_U, rb = cur.rb * KM_U, ex = Math.sin(t) * ra, ey = -Math.cos(t) * ra;
          const north = Math.max(ra, rb) * 0.9, arcR = Math.min(ra, north) * 0.55;
          const a0 = -Math.PI / 2, a1 = a0 + t; // arc from north (up) clockwise to the long axis
          const sweep = cur.bearing <= 180 ? 1 : 0;
          const ax = cx + Math.cos(a0) * arcR, ay = cy + Math.sin(a0) * arcR, bx = cx + Math.cos(a1) * arcR, by = cy + Math.sin(a1) * arcR;
          const mid = a0 + t / 2;
          return (
            <g style={{ pointerEvents: 'none' }}>
              <line x1={cx} y1={cy} x2={cx} y2={cy - north} stroke="#d5d9df" strokeWidth="1.2" strokeDasharray="2 5" vectorEffect="non-scaling-stroke" opacity="0.8" />
              <text x={cx + 4 * s} y={cy - north - 4 * s} fill="#d5d9df" fontSize={11 * s}>north</text>
              <path d={`M${ax},${ay} A${arcR},${arcR} 0 0 ${sweep} ${bx},${by}`} fill="none" stroke="#fff" strokeWidth="1.8" vectorEffect="non-scaling-stroke" />
              <text x={cx + Math.cos(mid) * (arcR + 14 * s)} y={cy + Math.sin(mid) * (arcR + 14 * s)} fill="#fff" fontSize={12 * s} fontWeight="700" textAnchor="middle">{Math.round(cur.bearing)}°</text>
              {axPts ? <path d={'M' + axPts.map((q) => `${X(q[1]).toFixed(1)},${Y(q[0]).toFixed(1)}`).join('L')} fill="none" stroke="#fff" strokeWidth="2" vectorEffect="non-scaling-stroke" /> : <line x1={cx - ex} y1={cy - ey} x2={cx + ex} y2={cy + ey} stroke="#fff" strokeWidth="2" vectorEffect="non-scaling-stroke" />}
              {(cur.pts || []).map((p, i) => {
                const inn = inOval(cur, p[0], p[1]), r = Math.min(10, 4.2 + Math.sqrt(p[2]) * 0.6) * s;
                return (
                  <g key={i}>
                    <circle cx={X(p[1])} cy={Y(p[0])} r={r + 1.8 * s} fill="none" stroke="#fff" strokeWidth="1" vectorEffect="non-scaling-stroke" opacity="0.9" />
                    <circle cx={X(p[1])} cy={Y(p[0])} r={r} fill={inn ? cur.color : '#0d1117'} fillOpacity={inn ? 0.9 : 0.85} stroke={cur.color} strokeWidth="2" vectorEffect="non-scaling-stroke"><title>{`${p[3] || `${p[0].toFixed(2)}°N ${p[1].toFixed(2)}°E`}: ${p[2]} ${unit}${inn ? '' : ' (outside the oval)'}`}</title></circle>
                    {typeof p[3] === 'string' && view.w < 3500 && <text x={X(p[1]) + (r + 5 * s)} y={Y(p[0]) + 3.5 * s} fill="#e6e9ee" fontSize={10.5 * s} style={{ paintOrder: 'stroke', stroke: '#0d1117', strokeWidth: 3 * s }}>{p[3].length > 22 ? `${p[3].slice(0, 21)}…` : p[3]}</text>}
                  </g>
                );
              })}
              <circle cx={cx} cy={cy} r={4.5 * s} fill="#fff" stroke="#000" strokeWidth="1" vectorEffect="non-scaling-stroke" />
            </g>
          );
        })()}
      </svg>
      <div className="tl-legend">{legend}</div>
      {cur && cov && (
        <div className="tl-readout" style={{ marginTop: 10, maxWidth: 'none', border: '1px solid #232a33', borderRadius: 8, padding: '10px 14px', background: '#11151b' }}>
          <p style={{ margin: '0 0 4px' }}><b style={{ fontSize: 14 }}>{cur.label}</b></p>
          {cur.facts && cur.facts.map((f, i) => <p key={i} style={{ margin: '2px 0' }}>{f}</p>)}
          <p style={{ margin: '4px 0 2px' }}>The oval is centred at {cur.lat.toFixed(1)}°N, {cur.lon.toFixed(1)}°E. Its long axis points <b>{Math.round(cur.bearing)}°</b> from north ({compass(cur.bearing)}–{compass(cur.bearing + 180)}); radii <b>{Math.round(cur.ra)} km</b> (long) and <b>{Math.round(cur.rb)} km</b> (short){scale !== 1 ? `, drawn at ${scale}× the size in the paper` : ''}, so it is {(cur.ra / cur.rb).toFixed(1)} times as long as wide.</p>
          {cities.length > 0 && <p style={{ margin: '2px 0' }}>Off the axis, seen from the oval's own centre: {cities.map((c, i) => <span key={c.name}>{i ? '; ' : ''}{c.name} <b>{Math.round(axisOff(cur.bearing, bearingTo(cur.lat, cur.lon, c.lat, c.lon)))}°</b></span>)}.</p>}
          {!cur.solid && <p style={{ margin: '4px 0 2px', color: '#aab1bb' }}>This oval is drawn dashed because it is less than 1.5 times as long as wide. A nearly round oval has no meaningful long axis, so it is given no direction.</p>}
          {cur.az && <p style={{ margin: '4px 0 2px', color: '#aab1bb' }}>This oval is fitted and drawn on an equidistant map projection centred on the oval, so a long oval across the ocean is curved like a great-circle route, and the angle and the off-axis angles above are true bearings from its centre. A flat map would bend such an oval and give a different angle.</p>}
          <p style={{ margin: '6px 0 2px' }}><b>Coverage: how many of the dots fall inside the oval</b></p>
          <ul style={{ margin: '0 0 0 18px', padding: 0 }}>
            <li><b>{cov.placesIn} of {cov.placesN} places</b> ({cov.placesN ? pctS(cov.placesIn / cov.placesN) : '–'}) lie inside the oval. Dots with a coloured fill are inside; dark dots are outside. Each dot has a white ring so that it stays visible over a city marker; Kyiv's own dot sits inside the dashed ring.</li>
            <li><b>{Math.round(cov.booksIn)} of {Math.round(cov.booksN)} {unit}</b> ({cov.booksN ? pctS(cov.booksIn / cov.booksN) : '–'}) name a place inside it (a book that names several places is counted once for each).</li>
            <li>For scale: an oval drawn at 1× is one standard deviation along each axis, which for places spread like a bell curve holds about 39% of them. At 2× it holds about 86%. Use "Oval size" above to see this heading's own figures.</li>
          </ul>
          {far.length > 0 && <p style={{ margin: '4px 0 2px' }}>{far.length} of the {cov.placesN} places are outside the part of the map now in view: {far.slice().sort((a, b) => b[2] - a[2]).slice(0, 6).map((p) => `${p[3] || `${p[0].toFixed(1)}°N ${p[1].toFixed(1)}°E`} (${p[2]})`).join('; ')}{far.length > 6 ? '; …' : ''}. Use "Show all dots" or "World" to see them.</p>}
          {!(cur.lat >= 44 && cur.lat <= 52.5 && cur.lon >= 22 && cur.lon <= 40.5) && <p style={{ margin: '4px 0 2px', color: '#c4b5fd' }}>{cur.na ? 'This oval is centred outside Ukraine, because the heading names many places abroad, and its long axis points towards the United States and Canada. It is counted as leaning towards North America, not towards a neighbour of Ukraine.' : fitCities ? 'This oval is centred outside Ukraine, because many of the imprints are abroad. Its long axis shows how far the imprints are spread.' : 'This oval is centred outside Ukraine, because the heading names many places abroad. Its long axis shows how far its places are spread, not a lean towards a neighbouring country, so it is not counted in the direction tests.'}</p>}
          {chance && (<>
            <p style={{ margin: '6px 0 2px' }}><b>Compared with random places</b> ({chance.n} random sets of {chance.k} places, drawn from all places in the collection)</p>
            <ul style={{ margin: '0 0 0 18px', padding: 0 }}>
              <li>Size: this heading's oval has a combined radius of <b>{Math.round(chance.own.rad)} km</b>; random sets of {chance.k} places have a median of {Math.round(chance.sizeMed)} km, and {pctS(chance.smaller)} of them are as compact or more so.</li>
              <li>Shape: this oval is <b>{chance.own.el.toFixed(1)}×</b> as long as wide; random sets have a median of {chance.elMed.toFixed(1)}×, and <b>{pctS(chance.shareEl)}</b> of them are at least 1.5× elongated, so being elongated is {chance.shareEl > 0.6 ? 'what chance usually gives at this size' : 'not usual for random sets of this size'}.</li>
              {cities.length > 0 && <li>Direction: among the elongated random sets, {cities.map((c, i) => <span key={c.name}>{i ? '; ' : ''}{pctS(chance.lean[c.name])} lean towards {c.name}</span>)} (within 22.5° of the bearing from each oval's own centre).</li>}
              {chance.bLo != null && <li>Stability: resampling this heading's own places, the long axis stays between <b>{Math.round(chance.bLo)}°</b> and <b>{Math.round(chance.bHi)}°</b> from north in 80% of resamples{chance.k < 15 ? ', which is wide: with so few places the direction is not reliable' : ''}.</li>}
            </ul>
            {chance.k < 15 && <p style={{ margin: '2px 0', color: '#e0b36a' }}>Small sample: only {chance.k} places. Read this oval as a summary to compare with chance, not as the heading's real footprint.</p>}
          </>)}
          <p style={{ margin: '6px 0 2px' }}><b>Variance explained</b></p>
          <ul style={{ margin: '0 0 0 18px', padding: 0 }}>
            {cov.varShare != null && <li>The variance of this heading's places (the sum of the squared radii of its oval, at 1×) is <b>{pctS(cov.varShare / (scale * scale))}</b> of the variance of all places in the collection, {cov.varShare / (scale * scale) >= 1 ? <>so these places are more spread out than places in the collection as a whole and the heading explains <b>none</b> of the variance in where a place lies.</> : <>so knowing the heading explains <b>{pctS(1 - cov.varShare / (scale * scale))}</b> of the variance in where a place lies (1 − within ÷ total, the same logic as R²).</>}</li>}
            <li>Of the oval's own spread, <b>{pctS(cov.alongAxis)}</b> lies along the long axis and {pctS(1 - cov.alongAxis)} across it.</li>
          </ul>
          {(cov.ovalInUkraine != null || cov.poolShare != null) && <p style={{ margin: '6px 0 2px' }}><b>Where the oval lies</b></p>}
          <ul style={{ margin: '0 0 0 18px', padding: 0 }}>
            {cov.ovalInUkraine != null && <li><b>{pctS(cov.ovalInUkraine)}</b> of the oval's area lies in Ukraine, and the oval covers <b>{pctS(cov.ukraineInOval)}</b> of Ukraine's area.</li>}
            {cov.poolShare != null && <li><b>{pctS(cov.poolShare)}</b> of all located place mentions in the whole collection fall inside it.</li>}
          </ul>
          {extra}
        </div>
      )}
    </div>
  );
}
