function applyLocalizedExplanations(root, language) {
  if (!root) return;
  const markCaption = root.querySelector('#markCaption');
  const readingShape = root.querySelector('#readingTheShape');
  if (!markCaption || !readingShape) return;
  const swap = (el, uk, wrapUk) => {
    if (!el) return;
    if (!el.dataset.englishHtml) el.dataset.englishHtml = el.innerHTML;
    const num = el.querySelector('#ukraineContextNum');
    const numText = num ? num.textContent : (el.dataset.num || '');
    if (numText) el.dataset.num = numText;
    el.innerHTML = language === 'uk' ? (wrapUk ? wrapUk(uk) : uk) : el.dataset.englishHtml;
    const n2 = el.querySelector('#ukraineContextNum');
    if (n2 && el.dataset.num) n2.textContent = el.dataset.num;
  };
  swap(markCaption, MARK_CAPTION_UK);
  swap(readingShape, READING_SHAPE_UK, (t) => `<b>Як читати форму діаграми:</b>${t}`);
  swap(root.querySelector('#irSubtitle'), SUBTITLE_UK);
  swap(root.querySelector('#recordCountNote'), COUNT_NOTE_UK);
  swap(root.querySelector('#irMeasures'), MEASURES_UK);
}

export default function InfluenceRiver() {
  const ref = useRef(null);
  const handleRef = useRef(null);
  const { tr, language } = useLocale();
  const trRef = useRef(tr);
  const languageRef = useRef(language);

  useEffect(() => {
    trRef.current = tr;
    languageRef.current = language;
    if (handleRef.current) handleRef.current.setTranslator(tr);
  }, [tr, language]);

  useEffect(() => {
    applyLocalizedExplanations(ref.current, language);
  }, [language]);

  useEffect(() => {
    let handle = null;
    let cancelled = false;
    const node = ref.current;

    if (node) {
      node.innerHTML = SKELETON_HTML;
      applyLocalizedExplanations(node, languageRef.current);
    }

    fetch(`${process.env.PUBLIC_URL}/data/influence_river.json`)
      .then((res) => res.json())
      .then((DATA) => {
        if (cancelled || !node) return;
        handle = initInfluenceRiver(node, DATA, trRef.current);
        handleRef.current = handle;
      })
      .catch((err) => {
        console.error('Failed to load influence_river.json', err);
      });

    return () => {
      cancelled = true;
      if (handle) handle.destroy();
      handleRef.current = null;
      if (node) node.innerHTML = '';
    };
  }, []);

  return <div ref={ref} />;
}
