import React, { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import './TestsLab.css';
import { MAP_W, MAP_H, NX, NY, projX, projY, prepareBooks, compute, smooth } from './homogeneityLogic';
import { HMap } from './HomogeneityMap';

const STOPS = ['#482878', '#3e4989', '#26828e', '#35b779', '#b5de2b', '#fde725'];
const K = Math.cos((48.5 * Math.PI) / 180) * 111;
const xMap = (lon) => projX(lon);

function mixColor(t) {
  const z = Math.max(0, Math.min(0.999999, t)) * (STOPS.length - 1);
  const i = Math.floor(z), f = z - i;
  const a = STOPS[i], b = STOPS[i + 1];
  return [1, 3, 5].map((k) => Math.round(parseInt(a.slice(k, k + 2), 16) * (1 - f) + parseInt(b.slice(k, k + 2), 16) * f));
}

function entropyExtent(grids) {
  let min = Infinity, max = -Infinity;
  grids.forEach((grid) => {
    if (!grid) return;
    for (const value of grid.Z) if (Number.isFinite(value)) { min = Math.min(min, value); max = Math.max(max, value); }
  });
  if (!Number.isFinite(min) || !Number.isFinite(max)) return [0, 1];
  if (max - min < 1e-6) return [min, min + 1];
  return [min, max];
}

function raster(smoothed, extent) {
  const [min, max] = extent;
  const canvas = document.createElement('canvas');
  canvas.width = NX; canvas.height = NY;
  const ctx = canvas.getContext('2d');
  const image = ctx.createImageData(NX, NY);
  for (let i = 0; i < smoothed.Z.length; i++) {
    const value = smoothed.Z[i];
    if (!Number.isFinite(value)) continue;
    const [r, g, b] = mixColor((value - min) / (max - min));
    image.data.set([r, g, b, 255], i * 4);
  }
  ctx.putImageData(image, 0, 0);
  return canvas.toDataURL();
}

function headingMass(ids, R) {
  const mass = new Map();
  let books = 0;
  for (const i of ids) {
    if (!R.active[i]) continue;
    const terms = R.vec[i].t;
    if (!terms.length) continue;
    books++;
    const perTerm = 1 / terms.length;
    for (const t of terms) mass.set(t, (mass.get(t) || 0) + perTerm);
  }
  return { mass, books };
}

function distinctivenessValues(P, R) {
  const values = new Float32Array(P.books.length).fill(NaN);
  const global = headingMass(P.books.map((_, i) => i), R);
  let usable = 0;
  for (let i = 0; i < P.books.length; i++) {
    if (!R.active[i]) continue;
    const ids = [i, ...P.near[i], ...P.same[i]];
    const local = headingMass(ids, R);
    if (local.books < 5) continue;
    let divergence = 0;
    local.mass.forEach((n, t) => {
      const pLocal = n / local.books, pGlobal = (global.mass.get(t) || 0) / global.books;
      if (pLocal > 0 && pGlobal > 0) divergence += pLocal * Math.log2(pLocal / pGlobal);
    });
    values[i] = divergence;
    usable++;
  }
  return { values, usable, global };
}

function distinctivenessAt(P, R, global, mapX, mapY) {
  const x = mapX + 22 * K;
  const y = 52.5 * 111 - mapY;
  const ids = [];
  for (let i = 0; i < P.books.length; i++) {
    const b = P.books[i];
    if (Math.hypot(b.x - x, b.y - y) <= 150) ids.push(i);
  }
  const local = headingMass(ids, R);
  if (local.books < 5 || !global.books) return null;
  let divergence = 0;
  const top = [];
  local.mass.forEach((n, t) => {
    const localShare = n / local.books, globalShare = (global.mass.get(t) || 0) / global.books;
    if (!(localShare > 0 && globalShare > 0)) return;
    const lift = localShare / globalShare;
    const contribution = localShare * Math.log2(lift);
    divergence += contribution;
    if (lift > 1) top.push({ label: P.vocab[t][0], localShare, globalShare, lift, contribution });
  });
  top.sort((a, b) => b.contribution - a.contribution);
  return { score: divergence, books: local.books, top: top.slice(0, 6) };
}

export function SubjectDistinctiveness({ embedded = false }) {
  const [raw, setRaw] = useState(null), [geo, setGeo] = useState(null), [error, setError] = useState(null);
  const [topicsOnly, setTopicsOnly] = useState(true), [showCities, setShowCities] = useState(true), [showCircles, setShowCircles] = useState(true);
  const [rad, setRad] = useState('both'), [view, setView] = useState({ x: 0, y: 0, w: MAP_W, h: MAP_H });
  const [sel, setSel] = useState({ group: null, book: null }), [spot, setSpot] = useState(null), [removed, setRemoved] = useState(() => new Set());
  useEffect(() => {
    const base = `${process.env.PUBLIC_URL}/data`;
    Promise.all([fetch(`${base}/homogeneity_books.json`).then((r) => r.json()), fetch(`${base}/homogeneity_geo.json`).then((r) => r.json())])
      .then(([a, b]) => { setRaw(a); setGeo(b); }).catch((e) => setError(String(e)));
  }, []);
  const P = useMemo(() => raw ? prepareBooks(raw) : null, [raw]);
  const R = useMemo(() => P ? compute(P, { paper: topicsOnly, noCrimea: false, removed }) : null, [P, topicsOnly, removed]);
  const E = useMemo(() => P && R ? distinctivenessValues(P, R) : null, [P, R]);
  const grid40 = useMemo(() => P && E && rad !== '80' ? smooth(P, { val: E.values }, 40) : null, [P, E, rad]);
  const grid80 = useMemo(() => P && E && rad !== '40' ? smooth(P, { val: E.values }, 80) : null, [P, E, rad]);
  const extent = useMemo(() => entropyExtent([grid40, grid80]), [grid40, grid80]);
  const img40 = useMemo(() => grid40 ? raster(grid40, extent) : null, [grid40, extent]);
  const img80 = useMemo(() => grid80 ? raster(grid80, extent) : null, [grid80, extent]);
  const groups = useMemo(() => {
    if (!P || !R || !geo) return null;
    const by = new Map(), of = new Array(P.books.length);
    P.books.forEach((b, i) => {
      const key = `${b.lat},${b.lon}`;
      let g = by.get(key);
      if (!g) { g = { key, lat: b.lat, lon: b.lon, idx: [], n: 0, active: 0, near: null }; by.set(key, g); }
      g.idx.push(i); g.n++;
      if (R.active[i]) g.active++;
      of[i] = key;
    });
    return { list: [...by.values()].filter((g) => g.n).sort((a, b) => b.n - a.n), by, of, books: P.books };
  }, [P, R, geo]);
  const detail = useMemo(() => P && R && E && spot ? distinctivenessAt(P, R, E.global, spot.x, spot.y) : null, [P, R, E, spot]);
  if (error) return <div className="tl-root"><p className="tl-err">Could not load the data: {error}</p></div>;
  if (!P || !R || !geo || !groups || !E) return <div className="tl-root"><p className="tl-muted">Loading diversity data…</p></div>;
  const choose = (g, bw) => { setSel({ group: g.key, book: null }); setSpot({ x: xMap(g.lon), y: projY(g.lat), bw }); };
  const remove = (ids) => setRemoved((old) => { const next = new Set(old); ids.forEach((id) => next.add(id)); return next; });
  const addBack = (ids) => setRemoved((old) => { const next = new Set(old); ids.forEach((id) => next.delete(id)); return next; });
  const selectedGroup = sel.group && groups ? groups.by.get(sel.group) : null;
  const removedBooks = [...removed].map((id) => P.books.find((b) => b.id === id)).filter(Boolean);
  const groupBooks = selectedGroup ? selectedGroup.idx.map((i) => ({ i, book: P.books[i] })) : [];
  const loc = (id) => `https://lccn.loc.gov/${encodeURIComponent(id)}`;
  const spotInfo = { kind: 'distinctiveness', drv: detail };
  const props = { spotInfo, dotFill: null, geo, groups, sel, neigh: null, showCities, showCircles, view, setView, onPick: choose, onSpot: setSpot, spot };
  return (
    <div className="tl-root">
      {!embedded && <p className="tl-back"><Link to="/homogeneity">← Homogeneity map</Link> · <Link to="/subjects-3d">3D relief</Link></p>}
      {embedded ? <h2>Locally distinctive subjects</h2> : <h1>Subject distinctiveness map</h1>}
      <p className="tl-lead">Each place is coloured by how different its subject-heading mix is from the collection overall. The score is local Kullback–Leibler divergence in bits, smoothed over 40 km or 80 km: higher values mean the area has a more distinctive mix. Click the map to see which headings contribute most to that local distinctiveness.</p>
      <div className="tl-toolbar">
        <label><input type="checkbox" checked={topicsOnly} onChange={(e) => setTopicsOnly(e.target.checked)} /> Exclude place, person, and generic headings</label>
        <label>Smoothing radius <select value={rad} onChange={(e) => setRad(e.target.value)}><option value="both">40 km and 80 km</option><option value="40">40 km</option><option value="80">80 km</option></select></label>
        <label><input type="checkbox" checked={showCircles} onChange={(e) => setShowCircles(e.target.checked)} /> Document circles</label>
        <label><input type="checkbox" checked={showCities} onChange={(e) => setShowCities(e.target.checked)} /> Dnipro and major cities</label>
      </div>
      <p className="tl-readout" style={{ maxWidth: 'none' }}><b>Records shown:</b> {R.n.toLocaleString()} of {P.books.length.toLocaleString()} points ({new Set(P.books.map((b) => b.id)).size.toLocaleString()} documents; a document about several places has a point for each, and one also in a pile at the centre has one more) have usable {topicsOnly ? 'topic' : 'subject'} headings{removed.size ? ` (${removed.size} removed by you)` : ''}. Local distinctiveness estimates require at least five nearby records; {E.usable.toLocaleString()} book-centred estimates meet that threshold.</p>
      <div className="tl-row" style={{ gap: 14 }}>
        {rad !== '80' && <HMap {...props} uid="diversity40" bw={40} title="Subject distinctiveness smoothed over 40 km" img={img40} />}
        {rad !== '40' && <HMap {...props} uid="diversity80" bw={80} title="Subject distinctiveness smoothed over 80 km" img={img80} />}
      </div>
      <div className="tl-legend" style={{ alignItems: 'center' }}>
        <span>less distinctive · {extent[0].toFixed(2)} bits</span><span style={{ display: 'inline-block', width: 220, height: 10, background: `linear-gradient(to right, ${STOPS.join(',')})`, borderRadius: 5 }} /><span>more distinctive · {extent[1].toFixed(2)} bits</span>
      </div>
      <div className="tl-row" style={{ marginTop: 18, gap: 24 }}>
        <div className="tl-col" style={{ flex: '1 1 420px' }}>
          <h3>{selectedGroup ? `Documents at this place (${selectedGroup.n})` : 'Documents at a selected place'}</h3>
          {!selectedGroup ? <p className="tl-muted" style={{ fontSize: 13 }}>Click a circle on either map to review its documents. Exclude any document from the analysis (all of its points go); excluded documents stay out even if the heading filter changes.</p> : (
            <div className="tl-tablewrap" style={{ maxHeight: 340 }}>
              <table className="tl-table" style={{ width: '100%' }}><tbody>
                {groupBooks.slice(0, 200).map(({ i, book }) => <tr key={book.id}>
                  <td><a href={loc(book.id)} target="_blank" rel="noopener noreferrer" style={{ color: '#7fb3ff' }}>{book.title || book.id}</a>{book.year ? <span className="tl-muted"> ({book.year})</span> : null}</td>
                  <td><button type="button" onClick={() => remove([book.id])} style={{ background: 'transparent', color: '#e3786a', border: '1px solid var(--border)', borderRadius: 5, cursor: 'pointer', font: 'inherit', fontSize: 12 }}>Exclude</button></td>
                </tr>)}
              </tbody></table>
              {groupBooks.length > 200 && <p className="tl-muted" style={{ fontSize: 12 }}>Showing the first 200 of {groupBooks.length} documents.</p>}
              <button type="button" className="tl-ghost" style={{ margin: '6px 0' }} onClick={() => remove(groupBooks.map(({ book }) => book.id))}>Exclude all documents at this place</button>
            </div>
          )}
        </div>
        <div className="tl-col" style={{ flex: '1.4 1 520px' }}>
          <h3>Removed documents ({removed.size})</h3>
          {!removed.size ? <p className="tl-muted" style={{ fontSize: 13 }}>None. Removed records no longer contribute to the local or collection-wide heading frequencies.</p> : <>
            <button type="button" className="tl-ghost" onClick={() => setRemoved(new Set())}>Add all back</button>
            <div className="tl-tablewrap" style={{ maxHeight: 280 }}><table className="tl-table"><tbody>
              {removedBooks.map((book) => <tr key={book.id}><td><a href={loc(book.id)} target="_blank" rel="noopener noreferrer" style={{ color: '#7fb3ff' }}>{book.title || book.id}</a>{book.year ? <span className="tl-muted"> ({book.year})</span> : null}</td><td><button type="button" onClick={() => addBack([book.id])}>Add back</button></td></tr>)}
            </tbody></table></div>
          </>}
        </div>
      </div>
      <p className="tl-note">Each active book contributes one unit split equally across its usable headings. The local heading distribution is compared with the distribution across the full active collection using Kullback–Leibler divergence; the highest-contributing headings are shown when you click. This highlights headings unusually concentrated in a place, not simply the most frequent headings. Grey areas have too little local data. The colour scale runs from the minimum to maximum local distinctiveness among the displayed smoothed cells.</p>
    </div>
  );
}


export default function DiversityMap() {
  return <SubjectDistinctiveness />;
}
