import React, { useEffect, useMemo, useRef, useState } from 'react';

// A pannable, zoomable world map. Coordinates are plain degrees, longitude scaled by cos(51°).
// Outline rings in world_outline.json are [lat, lon]; the Ukraine geojson is [lon, lat].
const KX = Math.cos((51 * Math.PI) / 180);
const W = 900, H = 540;
const P = (lat, lon) => [lon * KX, -lat];
const PRESETS = { World: [-170, 190, -58, 82], Europe: [-12, 62, 30, 66], 'East Europe': [10, 48, 40, 60], Slavic: [17, 46, 43, 57], Ukraine: [21, 41, 43, 54] };
const fit = ([lo0, lo1, la0, la1]) => {
  const bw = (lo1 - lo0) * KX, bh = la1 - la0, w = Math.max(bw, (bh * W) / H);
  return { cx: ((lo0 + lo1) / 2) * KX, cy: -(la0 + la1) / 2, w };
};

let WORLD = null;
export function useWorld() {
  const [w, setW] = useState(WORLD);
  useEffect(() => {
    if (WORLD) return undefined;
    let off = false;
    fetch(`${process.env.PUBLIC_URL}/data/world_outline.json`).then((r) => r.json()).then((x) => { WORLD = x; if (!off) setW(x); }).catch(() => {});
    return () => { off = true; };
  }, []);
  return w;
}

// The outlines never change while the arrows animate, so they are drawn by a memoised layer (no repaint of 250 country paths on every frame).
// Stroke widths are scaled with the zoom instead of using non-scaling strokes, which are slow for thousands of path points.
const BaseMap = React.memo(function BaseMap({ paths, ukd, u }) {
  return (
    <g>
      {paths && paths.map((d, i) => <path key={i} d={d} fill="none" stroke="currentColor" strokeWidth={0.8 * u} opacity="0.3" />)}
      {ukd.map((d, i) => <path key={`u${i}`} d={d} fill="rgba(111,177,255,0.07)" stroke="currentColor" strokeWidth={1.2 * u} opacity="0.7" />)}
    </g>
  );
});

export function ZoomMap({ world, geo, start = 'World', children, label = 'Map' }) {
  const [v, setV] = useState(fit(PRESETS[start]));
  const ref = useRef(null), drag = useRef(null);
  const h = (v.w * H) / W, x0 = v.cx - v.w / 2, y0 = v.cy - h / 2, u = v.w / W;
  const zoomAt = (fx, fy, f) => setV((o) => {
    const w2 = Math.min(400, Math.max(1.2, o.w * f)), hh = (o.w * H) / W, h2 = (w2 * H) / W;
    const px = o.cx - o.w / 2 + fx * o.w, py = o.cy - hh / 2 + fy * hh;
    return { w: w2, cx: px - fx * w2 + w2 / 2, cy: py - fy * h2 + h2 / 2 };
  });
  useEffect(() => {
    const el = ref.current; if (!el) return undefined;
    const onWheel = (e) => {
      e.preventDefault();
      const r = el.getBoundingClientRect();
      zoomAt((e.clientX - r.left) / r.width, (e.clientY - r.top) / r.height, e.deltaY > 0 ? 1.2 : 1 / 1.2);
    };
    el.addEventListener('wheel', onWheel, { passive: false });
    return () => el.removeEventListener('wheel', onWheel);
  }, []);
  const paths = useMemo(() => {
    if (!world) return null;
    const d = (ring) => ring.map(([la, lo], i) => { const [x, y] = P(la, lo); return `${i ? 'L' : 'M'}${x.toFixed(2)},${y.toFixed(2)}`; }).join('') + 'Z';
    return (world.countries || []).map((c) => (c.r || []).map(d).join(''));
  }, [world]);
  const ukd = useMemo(() => {
    const out = [];
    ((geo && geo.features && geo.features[0]) ? [geo.features[0].geometry] : []).forEach((g) => (g.type === 'Polygon' ? [g.coordinates] : g.coordinates).forEach((poly) => out.push(poly[0].map(([lo, la], i) => { const [x, y] = P(la, lo); return `${i ? 'L' : 'M'}${x.toFixed(2)},${y.toFixed(2)}`; }).join('') + 'Z')));
    return out;
  }, [geo]);
  const btn = { font: 'inherit', fontSize: 12, padding: '2px 9px', marginRight: 4, color: 'inherit', background: 'transparent', border: '1px solid var(--border)', borderRadius: 6, cursor: 'pointer' };
  return (
    <div>
      <div style={{ margin: '4px 0' }}>
        <button style={btn} onClick={() => zoomAt(0.5, 0.5, 1 / 1.6)} aria-label="Zoom in">+</button>
        <button style={btn} onClick={() => zoomAt(0.5, 0.5, 1.6)} aria-label="Zoom out">−</button>
        {Object.keys(PRESETS).map((k) => <button key={k} style={btn} onClick={() => setV(fit(PRESETS[k]))}>{k}</button>)}
        <span className="tl-muted" style={{ fontSize: 11.5, marginLeft: 6 }}>Scroll to zoom, drag to move.</span>
      </div>
      <svg ref={ref} width={W} height={H} viewBox={`${x0} ${y0} ${v.w} ${h}`} role="img" aria-label={label}
        style={{ display: 'block', maxWidth: '100%', height: 'auto', aspectRatio: `${W} / ${H}`, background: 'rgba(255,255,255,0.03)', borderRadius: 8, cursor: drag.current ? 'grabbing' : 'grab', touchAction: 'none' }}
        onPointerDown={(e) => { e.currentTarget.setPointerCapture(e.pointerId); drag.current = { x: e.clientX, y: e.clientY }; }}
        onPointerMove={(e) => {
          if (!drag.current) return;
          const r = e.currentTarget.getBoundingClientRect(), dx = ((e.clientX - drag.current.x) / r.width) * v.w, dy = ((e.clientY - drag.current.y) / r.height) * h;
          drag.current = { x: e.clientX, y: e.clientY }; setV((o) => ({ ...o, cx: o.cx - dx, cy: o.cy - dy }));
        }}
        onPointerUp={() => { drag.current = null; }} onPointerCancel={() => { drag.current = null; }}>
        <BaseMap paths={paths} ukd={ukd} u={u} />
        {children(u, P)}
      </svg>
    </div>
  );
}

// Footprints before and from 1991 with the largest movements of the optimal plan.
export function FootprintMap({ fp, geo, world }) {
  const mxp = Math.max(...fp.pre.map((p) => p[2])), mxq = Math.max(...fp.post.map((p) => p[2])), mxf = Math.max(...fp.flows.map((f) => f.m), 1e-9);
  return (
    <div>
      <ZoomMap world={world} geo={geo} start="World" label="Footprints before and from 1991">
        {(u, Pr) => (
          <g>
            {fp.flows.map((f, i) => { const a = Pr(f.a[0], f.a[1]), b = Pr(f.b[0], f.b[1]); return <line key={i} x1={a[0]} y1={a[1]} x2={b[0]} y2={b[1]} stroke="#e8d15a" strokeWidth={0.8 + 3.2 * Math.sqrt(f.m / mxf)} vectorEffect="non-scaling-stroke" opacity="0.55"><title>{`${Math.round(f.km)} km, ${(100 * f.m).toFixed(1)}% of the mass`}</title></line>; })}
            {fp.pre.map((p, i) => { const c = Pr(p[0], p[1]); return <circle key={`a${i}`} cx={c[0]} cy={c[1]} r={(2 + 9 * Math.sqrt(p[2] / mxp)) * u} fill="rgba(111,177,255,0.35)" stroke="#6fb1ff" strokeWidth="1" vectorEffect="non-scaling-stroke"><title>{`before 1991: ${p[2]} mentions`}</title></circle>; })}
            {fp.post.map((p, i) => { const c = Pr(p[0], p[1]); return <circle key={`b${i}`} cx={c[0]} cy={c[1]} r={(2 + 9 * Math.sqrt(p[2] / mxq)) * u} fill="rgba(242,166,90,0.35)" stroke="#f2a65a" strokeWidth="1" vectorEffect="non-scaling-stroke"><title>{`from 1991: ${p[2]} mentions`}</title></circle>; })}
          </g>
        )}
      </ZoomMap>
      <div className="tl-muted" style={{ fontSize: 11.5, margin: '4px 0' }}>
        <span style={{ color: '#6fb1ff' }}>●</span> before 1991 · <span style={{ color: '#f2a65a' }}>●</span> from 1991 on · <span style={{ color: '#e8d15a' }}>━</span> largest movements of the optimal plan (thickness = share of the mass moved)
      </div>
    </div>
  );
}

const ERA_COL = ['#8fb4ff', '#6c8cf5', '#a56cf0', '#d06ad6', '#f26b8a', '#f59a5a', '#f2d65a'];
const CITIES = [['Kyiv', 50.45, 30.52], ['Moscow', 55.756, 37.617], ['Warsaw', 52.23, 21.01], ['Istanbul', 41.01, 28.98]];

// One ellipse per time period for one heading: how the footprint changes shape and moves.
// One small panel per period, with the previous period's ellipse as a dashed ghost, so the changes are easy to follow.
function Panels({ ell, eras, geo }) {
  const lo0 = 20, lo1 = 42, la0 = 43, la1 = 54, w = 250, h = Math.round(((la1 - la0) / ((lo1 - lo0) * KX)) * w);
  const X = (lo) => ((lo - lo0) * KX / ((lo1 - lo0) * KX)) * w, Y = (la) => ((la1 - la) / (la1 - la0)) * h;
  const pts = (poly) => poly.map(([la, lo]) => `${X(lo).toFixed(1)},${Y(la).toFixed(1)}`).join(' ');
  const uk = [];
  ((geo && geo.features && geo.features[0]) ? [geo.features[0].geometry] : []).forEach((g) => (g.type === 'Polygon' ? [g.coordinates] : g.coordinates).forEach((poly) => uk.push(poly[0].map(([lo, la], i) => `${i ? 'L' : 'M'}${X(lo).toFixed(1)},${Y(la).toFixed(1)}`).join('') + 'Z')));
  let prev = null;
  return (
    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10, margin: '8px 0' }}>
      {eras.map((n, i) => {
        const e = ell[i], p = prev; if (e) prev = e;
        return (
          <svg key={n} width={w} height={h + 20} role="img" aria-label={n} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8, maxWidth: '100%' }}>
            <text x="8" y="14" fontSize="11.5" fill={ERA_COL[i]}>{n}{e ? ` · ${e.rec} records` : ''}</text>
            <g transform="translate(0,20)">
              {uk.map((d, k) => <path key={k} d={d} fill="rgba(111,177,255,0.07)" stroke="currentColor" strokeWidth="0.8" opacity="0.6" />)}
              {p && <polygon points={pts(p.poly)} fill="none" stroke="currentColor" strokeWidth="1" strokeDasharray="3 3" opacity="0.45" />}
              {e ? <g><polygon points={pts(e.poly)} fill={ERA_COL[i]} fillOpacity="0.15" stroke={ERA_COL[i]} strokeWidth="2" /><circle cx={X(e.lon)} cy={Y(e.lat)} r="3.5" fill={ERA_COL[i]} /></g> : <text x={w / 2} y={h / 2} fontSize="11" textAnchor="middle" fill="currentColor" opacity="0.5">too few places</text>}
            </g>
          </svg>
        );
      })}
    </div>
  );
}

export function EraEllipseMap({ ell, eras, geo, world }) {
  const [on, setOn] = useState(() => eras.map(() => true));
  const rows = ell.map((e, i) => ({ e, i })).filter((r) => r.e);
  const path = rows.filter((r) => on[r.i]);
  return (
    <div>
      <div style={{ fontSize: 12.5, margin: '4px 0 6px' }}>
        {eras.map((n, i) => (
          <label key={n} style={{ marginRight: 12, opacity: ell[i] ? 1 : 0.4, whiteSpace: 'nowrap' }}>
            <input type="checkbox" disabled={!ell[i]} checked={!!ell[i] && on[i]} onChange={() => setOn((o) => o.map((x, j) => (j === i ? !x : x)))} />
            <span style={{ color: ERA_COL[i] }}> ━ </span>{n}{ell[i] ? ` (${ell[i].rec} records)` : ' (too few places)'}
          </label>
        ))}
      </div>
      <Panels ell={ell} eras={eras} geo={geo} />
      <div className="tl-muted" style={{ fontSize: 11.5, margin: '0 0 10px' }}>One panel per period; the dashed ellipse is the previous period with an ellipse. Below, all periods on one map that you can zoom.</div>
      <ZoomMap world={world} geo={geo} start="Ukraine" label="Ellipse of the places of a heading in each time period">
        {(u, Pr) => (
          <g>
            {CITIES.map(([n, la, lo]) => { const c = Pr(la, lo); return <g key={n}><circle cx={c[0]} cy={c[1]} r={2.5 * u} fill="currentColor" opacity="0.7" /><text x={c[0] + 4 * u} y={c[1] - 3 * u} fontSize={11 * u} fill="currentColor" opacity="0.7">{n}</text></g>; })}
            {path.length > 1 && <polyline points={path.map((r) => Pr(r.e.lat, r.e.lon).join(',')).join(' ')} fill="none" stroke="currentColor" strokeWidth="1" strokeDasharray="4 3" vectorEffect="non-scaling-stroke" opacity="0.5" />}
            {path.map(({ e, i }) => {
              const c = Pr(e.lat, e.lon);
              return (
                <g key={i}>
                  <polygon points={e.poly.map(([la, lo]) => Pr(la, lo).join(',')).join(' ')} fill={ERA_COL[i]} fillOpacity="0.1" stroke={ERA_COL[i]} strokeWidth="2" vectorEffect="non-scaling-stroke"><title>{`${eras[i]}: ${e.rec} records, ${e.n} places, elongation ${e.elong}, long axis ${e.bearing}° from north`}</title></polygon>
                  <circle cx={c[0]} cy={c[1]} r={3.5 * u} fill={ERA_COL[i]} stroke="#000" strokeWidth="0.5" vectorEffect="non-scaling-stroke" />
                </g>
              );
            })}
          </g>
        )}
      </ZoomMap>
      <div className="tl-muted" style={{ fontSize: 11.5, margin: '4px 0' }}>
        Each ellipse is the standard deviational ellipse of the places named in records of that period (the same construction as in the paper; at least five places). Dots mark the centres, joined in time order by the dashed line. Hover an ellipse for its numbers.
      </div>
      <table style={{ borderCollapse: 'collapse', fontSize: 12, margin: '4px 0 12px' }}>
        <thead><tr style={{ textAlign: 'left' }}>{['Period', 'Records', 'Places', 'Elongation', 'Long axis (° from north)'].map((t) => <th key={t} style={{ padding: '3px 14px 3px 0', borderBottom: '1px solid var(--border)' }}>{t}</th>)}</tr></thead>
        <tbody>{rows.map(({ e, i }) => <tr key={i}><td style={{ padding: '2px 14px 2px 0', color: ERA_COL[i] }}>{eras[i]}</td><td style={{ padding: '2px 14px 2px 0' }}>{e.rec}</td><td style={{ padding: '2px 14px 2px 0' }}>{e.n}</td><td style={{ padding: '2px 14px 2px 0' }}>{e.elong}</td><td style={{ padding: '2px 14px 2px 0' }}>{e.bearing}</td></tr>)}</tbody>
      </table>
    </div>
  );
}
